INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000003', 'ACOPLE FLEX RAN UL/FM 3". P1N 89 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 7246.0, 0.7329063284095714, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '3"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "1N Standard Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.13, fila 80mm/3": A=115mm, B=160mm, C=45mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf, pag.13, tabla 1N -- confirma exacto el valor ya cargado desde el recorte de una sola pagina, ahora con fuente limpia adicional', 828.00, 'Caja envolvente real A x B x C = 115 x 160 x 45 mm, confirmado en 2 fuentes (recorte individual + catalogo maestro completo, valores identicos).', 'alta (confirmado en 2 fuentes reales, sin ambiguedad)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000002', 'ACOPLE FLEX RAN UL/FM 2". P1N 60 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 9350.0, 0.6858136167268275, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "1N Standard Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.13, fila 50mm/2": A=83mm, B=125mm, C=44mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf (encontrado via WordPress REST API media search, referenciado en el pie de pagina de otras fichas MECH como "01-GROOVED BROCHURE V12"), pag.13, tabla 1N -- fila limpia, sin corrupcion (a diferencia del recorte de una sola pagina usado antes)', 456.50, 'Caja envolvente real A x B x C = 83 x 125 x 44 mm, lectura directa y limpia del catalogo maestro completo -- reemplaza el valor anterior (473.00 cm3, supuesto de reduccion) porque ahora si existe una fuente limpia y sin ambiguedad para esta talla.', 'alta (fila real limpia del catalogo maestro completo, coincide exacto con la talla del codigo interno, sin supuesto ni corrupcion de texto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000212', 'ACOPLE FLEX RAN UL/FM  2-1/2". P1N 73 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 11231.0, 0.6497466254368348, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '2-1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "1N Standard Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.13, fila 65mm/2½" O.D.73.0mm: A=96mm, B=143mm, C=45mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf, pag.13, tabla 1N -- confirma exacto el valor ya cargado, ahora con fuente limpia adicional', 617.76, 'Caja envolvente real A x B x C = 96 x 143 x 45 mm, confirmado en 2 fuentes (texto oculto de recorte individual + catalogo maestro completo, valores identicos).', 'alta (confirmado en 2 fuentes reales, sin ambiguedad)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000006', 'ACOPLE FLEX RAN UL/FM 6". P1NS 168 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 5818.0, 0.7827460700250087, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '6"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "1NS Light-duty Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.15, fila 165mm/6" O.D.168.3mm: A=200mm, B=266mm, C=52mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf, pag.15, tabla 1NS -- version limpia de la misma fila que antes se leyo de texto oculto/corrupto de un recorte individual (B=265 vs 266, diferencia menor de OCR)', 2766.40, 'Caja envolvente real A x B x C = 200 x 266 x 52 mm, lectura limpia del catalogo maestro completo.', 'alta (fila real limpia del catalogo maestro completo, coincide exacto con la talla del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000004', 'ACOPLE FLEX RAN UL/FM 4". P1N 114 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 10117.0, 0.6660284820522927, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "1N Standard Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.13, fila 100mm/4" O.D.114.3mm (variante correcta, el codigo interno dice "114"): A=145mm, B=198mm, C=50mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf, pag.13, tabla 1N -- CORRECCION: el recorte de una sola pagina usado antes solo tenia legible la variante O.D.108.0mm (la variante 114.3mm estaba corrupta/superpuesta en ese PDF recortado); el catalogo maestro completo si trae ambas variantes limpias, y el codigo interno "P1N 114" coincide exacto con la variante 114.3mm, no la 108.0mm que se habia usado por error', 1435.50, 'Caja envolvente real A x B x C = 145 x 198 x 50 mm (variante O.D. 114.3mm, la que coincide con el codigo interno) -- reemplaza el valor anterior (1311.00 cm3, variante O.D. 108.0mm incorrecta).', 'alta (fila real limpia del catalogo maestro completo, coincide exacto con la talla del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73A3B2A1', '573789155 TY3331 HSW QR CR SC K5.6 155°F 68°C 1/2" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 3659.0, 0.8489442812088059, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | TFP176 (Series TY-FRB Horizontal Sidewall): Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Beryllium Nickel w/TEFLON | Bulb: Glass | HSW Deflector: Bronze. Sin volumen: forma de sidewall con deflector tipo abanico (no redondo), la ficha no da un diámetro de cuerpo claro distinto del escudo (73mm). || RESUELTO 2026-08-11: ficha TFP176 confirmada exacta para SIN TY3331 (encontrada via referencia "Technical Data Sheet: TFP176" en el Price Book Section 1), Figura 1 trae diagrama acotado completo (no solo el escudo). Ver volumen_metodo.', NULL, NULL, 'Diámetro (deflector, punto más ancho): 1-13/16" (46.0mm) | Largo (cuerpo total, cara de conexión a superficie de asiento del escudo): 2-3/16" (55.6mm) - Modelo TY-FRB Horizontal Sidewall SIN TY3331, Figura 1', NULL, 92.40, 'Cilindro envolvente: pi x (diametro/2)^2 x largo, usando diametro del deflector (46.0mm, punto mas ancho, ficha TFP176 Figura 1, SIN TY3331 exacto) y largo total del cuerpo (55.6mm, cara de conexion a superficie de asiento del escudo, misma figura). Deflector real tipo abanico, no un disco perfecto -> sobrestimacion leve intencional (mismo criterio ya usado en TY9226 ESFR, codigo 78C7C4B3).', 'media (dimensiones reales de la ficha tecnica exacta del SIN TY3331 -- Figura 1 de TFP176, encontrada via el Price Book de tyco-fire.com -- pero la forma real del deflector no es un cilindro perfecto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PQBROI12', 'TY3531 517921155 PD QR BR K5.6 155°F 68°C 1/2" OCULTO INCH TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 11602.0, 0.6380932434818672, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | TFP181 (Series RFII "Royal Flush II" Concealed Pendent): Frame: Bronze | Support Cup: Plated Steel | Guide Pins: Stainless Steel | Deflector: Bronze | Compression Screw: Brass | Bulb: Glass | Cap: Bronze or Copper | Cover Plate: Brass | Retainer: Brass. Sin volumen: la ficha no trae dibujo acotado con medidas numéricas. || RESUELTO 2026-08-11: ficha TFP181 confirmada exacta para SIN TY3531 (encontrada via referencia "Technical Data Sheet: TFP181" en el Price Book Section 1). Figura 2 (pagina 3 de 4) trae C/D del conjunto sprinkler+support cup, distinto de las dimensiones A/B del escudo (Cover Plate) ya usadas en 72ESBLI012. Ver volumen_metodo.', NULL, NULL, 'Diámetro agujero de paso C: 2-3/8 a 2-5/8" (60.3-66.7mm) | Profundidad instalada D: 1-3/4 a 2-1/4" (44.5-57.2mm) - Modelo RFII Concealed Pendent SIN TY3531, Figura 2 (conjunto cuerpo+copa de soporte, no el escudo)', NULL, 161.03, 'Cilindro envolvente: pi x (diametro/2)^2 x largo, usando el punto medio del rango de diametro de agujero de paso C (60.3-66.7mm, ficha TFP181 Figura 2) y el punto medio del rango de profundidad instalada D (44.5-57.2mm, misma figura). Son dimensiones de holgura de instalacion del conjunto cuerpo+copa de soporte -- distintas del escudo/cover plate, que ya se cargo aparte en el codigo 72ESBLI012 con sus propias dimensiones A/B.', 'media (dimensiones C/D reales de la ficha tecnica exacta del SIN TY3531 -- Figura 2 de TFP181 -- pero son rango de holgura de instalacion, se uso el punto medio de cada rango, no una medida fija unica)');
