INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PQRBRO12', 'RA3415 PD. QR. BRONCE OCULTO K5.6 165°F 74°C 1/2" G5-56. G51B / 1916173299 - RASCO RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 7082.0, 0.7420367444448549, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Latón/Bronce (Brass/Bronze) - Body: Brass Alloy | Levers/Deflector/Load Screw: Bronze Alloy | Cup: Steel', NULL, NULL, NULL, '1/2"', '5.6 (80)', 'CORREGIDO 2026-08-11: el boletin correcto es el 034 (Model G5 Series, agosto 2024, encontrado via busqueda web dirigida por SIN), no el 051 revisado en una ronda anterior (ese era para SIN RA5114, modelo DRY concealed distinto). SIN RA3415 = Model G5-56 Standard Coverage Concealed Pendent, confirmado exacto contra la tabla de SIN del boletin (Tabla A, pagina 1). Material: Sprinkler Body Brass Alloy | Levers Bronze Alloy | Yoke Brass Alloy | Load Screw Bronze Alloy | Deflector Bronze Alloy | Cup Steel. Figura 3 (Sprinkler Components and Dimensions, pagina 4 de 9) da diametro real del cuerpo/cup: 2-5/16" (58mm) -- pero NO acota una altura total del cuerpo del rociador solo (el unico otro numero, D=1-3/4 a 2-1/4", es la holgura de instalacion del conjunto completo con cover plate, no la altura del cuerpo). Sin volumen: falta el eje de altura del cuerpo. Ficha incorrecta anterior archivada en capturas_fuentes/reliablesprinkler.com/ficha_real_g5-56-dry-concealed_bulletin051_NO_MATCH.pdf; ficha correcta guardada como ficha_real_bulletin034_G5-56.pdf.', NULL, NULL, 'Diámetro cuerpo/copa (cup): 2-5/16" (58mm) - Modelo G5-56 SIN RA3415, Figura 3, Boletín 034', NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('1A1JINA114', 'TUBO AC  C/C ASTM 795 Gr A SCH 10 1 - 1/4" UL/FM - MECH', 'MECH', 'JINAN MEIDE', 'TUBERIA', 4698.0, 0.8195677694825326, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Acero al carbono soldado (Welded Carbon Steel), ASTM A795/A53', NULL, NULL, NULL, '1/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: meide.mx (texto ya guardado en scrapes: tubería de acero soldada)', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B32000031', 'TE MEC SAL ROS UL/FM  3" X 1". P3JS 89X34 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 4887.0, 0.8159201202810527, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '3" x 1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Talla 3x1: medidas (152, 72.5, 80) mm (ver volumen_metodo)', 'Ficha PDF real (botón Download) fu-mech.com/product/mech-grooved-mech-tee-thd-model-3j/. Tabla ''3J'', columnas Nominal Size/Pipe O.D./Hole Dia/Dimensions A,B,C,D/Bolt Size. Fila 100x65 (4x2-1/2) recuperada de texto embebido fuera del área visible de la página (continuación de la misma tabla en la página siguiente del catálogo original) -- ver nota de la ronda ''revisión MECH thumbnails'' 2026-08-10.', 881.6, 'Caja envolvente real: A×B×C = 152×72.5×80 mm, tabla oficial UL/FM por talla nominal.', 'alta (3 ejes reales de tabla oficial del fabricante, sin supuestos)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('23BOQP0112', 'BOQUILLA CHORRO NIEBLA POLICARBONATO 11/2". HN4L RED NST - WILSON & COUSINS', 'WILSON & COUSINS', 'WILSON & COUSIN', 'VALVULAS', 4452.0, 0.8289625451207943, 'wilsonandcousins.com', true, '2026-08-04 15:14:44.141571+00', 'Plástico (Red Plastic)', NULL, NULL, NULL, '11/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado en descripción del producto (wilsonandcousins.com)', NULL, NULL, 'A: 2.38" (59mm) | C cerrado: 5" (127mm)', 'wilsonandcousins.com, Contractor-Specs-HN4L-RED-3.pdf', 442.09, 'Caja envolvente: A×B×C = 59.0×59.0×127.0 mm (cuerpo tipo válvula/boquilla).', 'baja (sin ancho B publicado, se usa A como aproximación)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6D4PHD1038', 'BEAM CLAMP W/L FIG 353  3/8" PHD (300)', 'PHD', 'RELIABLE', 'SOPORTERIA', 27748.0, 0.4780789423973257, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron with hardened steel cup point set screw and locknut', 'Plain or electro-galvanized (Hot dipped galvanized with electro-galvanized hardware upon request)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for sizes 3/8” to 7/8” only. Factory Mutual Approved for rod sizes 3/8” and 1/2” only. Complies with Federal Specifications A-A-1192A (Type 19) and Manufacturers’ Standardization Society ANSI/MSS SPSP-58 (Type 19) which supersedes ANSI/MSS SP-69. Fig. 353 sized for 3/8” rod can be used in an inverted position (bottom of beam) and follows the same U.S. (UL), Canada (CUL), and Factory Mutual Approvals. Used in this manner the 3/8” Fig. 353 also complies with Federal Specifications A-A-1192A (Type 23) and Manufacturers’ Standardization Society ANSI/MSS SPSP-58 (Type 23) which supersedes ANSI/MSS SP-69. (Approvals are only valid for beam clamps with locknut). Buy American Act compliant.', 'Designed for attaching hanger rod to the top flange of a beam or bar joist, where the flange thickness does not exceed 3/4” (19.05mm). The open U design permits rod adjustment. The universal design of the 3/8” Fig. 353 allows it to be used in an inverted position on the bottom flange of a beam as well.', '3/8"', NULL, 'Ordering: Specify figure number, rod size, and finish. | Note: When a torque wrench is unavailable, the setscrew should be tightened so it contacts the I-beam and then an additional 1/4  to 1/2 turn. | Tamaño derivado del propio código interno, no de ficha del fabricante', 0.33, 0.15, 'Rod Size A: 3/8 | B: 7/8 | C: 11/2 | D: 15/8 | E: 1/2 | Max. Pipe Size: 4 | Max. Rec. Load: 400', 'https://www.phd-mfg.com/wp-content/uploads/2025/12/350353354355356357_11-12-25.pdf', 147.82, 'Caja envolvente: D×C×B = 47.62×139.7×22.22 mm, tomado de una ficha con 2 vistas reales (frontal: D=alcance de la mordaza, C=altura; lateral: B=ancho de la base). Las 3 medidas vienen del dibujo técnico, no son un supuesto.', 'media (3 ejes de un dibujo real de 2 vistas)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73UPQRCR12', '773709155 TY313 UP QR CR K5.6  155°F 68°C 1/2" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 39305.0, 0.3978750621116736, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-05: el material anterior venía de TFP110 (Series TY-L, tipo fusible/soldadura) pero este código es Series TY-FRB (tipo bulbo de vidrio) según TFP172 -- son productos físicamente distintos. Material real pendiente de recargar desde TFP172. | Desglose TFP172 (Physical Characteristics, Series TY-FRB): Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Stainless Steel w/TEFLON | Bulb: Glass | Compression Screw: Bronze | Deflector: Bronze.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2" (50.8mm)', 'tyco-fire.com, TFP172.pdf, Figura 1/4/5 -- coincide exacto con SIN TY313/TY323 (no confundir con el 2-7/8"/73mm que es el escudo empotrado, un accesorio aparte)', 130.54, 'Cilindro real: π×(diámetro/2)²×largo = π×(28.6)²×50.8 mm. Pieza redonda de verdad (no abrazadera irregular), diámetro y largo confirmados con diagrama revisado a mano.', 'alta (dimensiones exactas del fabricante para el SIN exacto, verificado con el diagrama)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('25EXHDF004', 'RESTRICTORES - TUF GRIP (HEXAGONAL) HD 4" (CON KIT EMP. TORN) 114253 - TYLER UNION', 'TYLER UNION', 'MC WANE', 'C900', 3725.5, 0.8470544950372257, 'tylerunion.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron)', NULL, NULL, NULL, '4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso = "Weight (w/Acc.)" (100% Domestic, con kit de accesorios) que coincide con "CON KIT EMP. TORN" del nombre de nuestro código. Es un collar que rodea la tubería, no una pieza sólida.', 11.8, 5.35, 'C: 4.93" (125.2mm) | D: 5.92" (150.4mm) | E: 7.50" (190.5mm) | K2: 8.98" (228.1mm) | J: 10.67" (271.0mm) | Pipe O.D.: 4.80" (121.9mm)', 'tylerunion.com, tufgrip-1000-tld-domestic-submittal.pdf (tabla "TUFGrip MJ Restraint Dimensions" + "Application Chart", talla 4")', 9911.64, 'Caja envolvente: K2 (diámetro máximo con cuñas) × K2 × E (largo a lo largo del eje de tubería) = 228.1×228.1×190.5 mm. Es un collar que rodea la tubería, la caja sobrestima el volumen real (hueco en el centro), pero es razonable para espacio de bodega.', 'media (3 ejes de ficha real, pero forma de anillo hueco -- la caja es una sobrestimación intencional)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73EBROW512', 'ESCUDO BLANCO P/ROCIADR OCULTO MOD. G5 / CG50W / CG50E - 6887271372 - RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 7729.0, 0.7157350172270062, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Plato: laton acabado; falda (skirt): acero cobrizado (copper plated steel); resorte: laton', 'Blanco (pintado)', NULL, NULL, NULL, NULL, 'Peso no publicado por el fabricante en fichas de placas de cobertura', NULL, NULL, 'Diametro de plato 3-5/16" (84mm), hueco recomendado en cielo raso 2-5/8" (67mm), protrusion desde el cielo raso 3/16" (4mm) - Modelo G5', 'reliablesprinkler.com, Bulletin 203 (Sprinkler Cover Plates), especificaciones Modelo G5, marzo 2024', 22.17, 'cilindro envolvente (diametro de plato x protrusion) segun especificacion de catalogo Modelo G5', 'media (modelo G5 confirmado por nombre_producto "MOD. G5/CG50W"; dimension tomada de tabla de especificaciones, no de diagrama acotado con figura)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('5A32VSRB212', 'VALVULA ANGULAR STDAR 2 1/2" BR HxM C/TAPA BRONCE C/C. IE23E NST - WILSON & COUSINS', 'WILSON & COUSINS', 'WILSON & COUSIN', 'VALVULAS', 7136.0, 0.7365706604986179, 'wilsonandcousins.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass)', NULL, NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado en nombre/URL del producto (wilsonandcousins.com)', NULL, NULL, 'A: 5" (125mm) | B: 3-3/16" (79mm) | C abierto: 11" (275mm) | C cerrado: 9-1/4" (231mm)', 'wilsonandcousins.com, Contractor-Specs-IE23-2.pdf', 2281.12, 'Caja envolvente: A×B×C = 125.0×79.0×231.0 mm (cuerpo tipo válvula/boquilla).', 'media (3 medidas de cuerpo de válvula ya publicadas)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B32000021', 'TE MEC SAL ROS UL/FM  2 " X 1" MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 7434.0, 0.7254085254175341, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Talla 2x1: medidas (116, 68, 60) mm (ver volumen_metodo)', 'Ficha PDF real (botón Download) fu-mech.com/product/mech-grooved-mech-tee-thd-model-3j/. Tabla ''3J'', columnas Nominal Size/Pipe O.D./Hole Dia/Dimensions A,B,C,D/Bolt Size. Fila 100x65 (4x2-1/2) recuperada de texto embebido fuera del área visible de la página (continuación de la misma tabla en la página siguiente del catálogo original) -- ver nota de la ronda ''revisión MECH thumbnails'' 2026-08-10.', 473.28, 'Caja envolvente real: A×B×C = 116×68×60 mm, tabla oficial UL/FM por talla nominal.', 'alta (3 ejes reales de tabla oficial del fabricante, sin supuestos)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('SI40989792', '4098-9792 BASE DIRECCIONABLE PARA SENSORES - SIMPLEX', 'SIMPLEX', 'SIMPLEX', 'DETECCION', 12908.0, 0.6256845117098468, 'johnsoncontrols.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.5, 0.227, '0.29" (7.4mm) x 2.5" (63.5mm) x 5.25" (133.4mm)', 'lifesafetycom.com (distribuidor) -- OJO: otra fuente (Amazon) dice el diámetro con brida es 4.875", no coincide bien con estas 3 medidas', 246.7, 'Caja aproximada: 0.29"×2.5"×5.25" = 7.4×63.5×133.4 mm. Confianza baja -- las medidas no calzan claramente con una base circular con brida de 4.875" que menciona otra fuente.', 'baja (fuente única de distribuidor, con inconsistencia frente a otra fuente sobre el diámetro)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73UPSRBR12', '775701155 TY315 UP SR BR K5.6 155°F 68°C 1/2"', 'TYCO', 'TYCO', 'SPRINKLES', 7306.0, 0.7291739814712149, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-10: material anterior venía de TFP110 (Series TY-L) por error -- este código es Series TY-B (bulbo de vidrio 5mm) según TFP152, documento distinto. Desglose TFP152: Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Stainless Steel w/TEFLON | Bulb: Glass.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2" (50.8mm)', 'tyco-fire.com, TFP152.pdf, Figura 1 -- coincide exacto con SIN TY315/TY325', 130.54, 'Cilindro real: π×(28.6)²×50.8 mm. Mismas dimensiones que TY313/TY323 (misma familia de cuerpo, distinto bulbo 5mm vs 3mm).', 'alta (dimensiones exactas del fabricante para el SIN exacto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73UPSRCR12', 'TY315 775709155 UP SR CR K5.6 155°F 68°C 1/2"', 'TYCO', 'TYCO', 'SPRINKLES', 14487.0, 0.5977931619667122, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-10: material anterior venía de TFP110 (Series TY-L) por error -- este código es Series TY-B (bulbo de vidrio 5mm) según TFP152, documento distinto. Desglose TFP152: Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Stainless Steel w/TEFLON | Bulb: Glass.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2" (50.8mm)', 'tyco-fire.com, TFP152.pdf, Figura 1 -- coincide exacto con SIN TY315/TY325', 130.54, 'Cilindro real: π×(28.6)²×50.8 mm. Mismas dimensiones que TY313/TY323 (misma familia de cuerpo, distinto bulbo 5mm vs 3mm).', 'alta (dimensiones exactas del fabricante para el SIN exacto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B33000021', 'STRAP (TEE MEC) UL/FM  2" X 1". P3L 60X34 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 41809.0, 0.3774711206383232, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '2" x 1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Modelo 3L/MT1, 2"x1" (50X25): A=66.6mm, B=95.3mm, C=57.2mm', 'meide.mx, ficha individual DS-400-MT1-01-E (U-Bolt Mechanical Tee), pag.4, tabla completa por combinacion nominal x hueco', 363.05, 'Caja envolvente real A x B x C = 66.6 x 95.3 x 57.2 mm, medidas directas de la ficha del fabricante (A=altura, B=ancho, C=profundidad del U-bolt).', 'alta (tabla A/B/C real y completa de ficha individual del fabricante, coincide exacto con la combinacion del codigo interno)');
