INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B33011434', 'STRAP  (TEE MEC) UL/FM  1-1/4" X 3/4". P3L 42X27 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 5955.0, 0.7782225692262834, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/4" x 3/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Modelo 3L/MT1, 1¼"x3/4" (32X20): A=54.4mm, B=88.9mm, C=57.2mm', 'meide.mx, ficha individual DS-400-MT1-01-E (U-Bolt Mechanical Tee), pag.4', 276.61, 'Caja envolvente real A x B x C = 54.4 x 88.9 x 57.2 mm.', 'alta (tabla A/B/C real y completa de ficha individual del fabricante, coincide exacto con la combinacion del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SATPHD004', 'SOP ANTIS TRANSV 4" PHD FIG. 015 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 5865.0, 0.7812528232578957, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada (21/2” thru 6” only) and Factory Mutual approved. Listed for use with NFPA and PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance. The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting, and joined together with a bracing pipe element forms a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '4"', NULL, 'Size: Pipe size 21/2” thru 8”. | Install: Place over the pipe to be braced, adjust brace angle, and insert bracing pipe through opening leaving a minimum of 1” extending from attachment. Brace pipe can be installed on top or bottom of pipe to be braced but must be a minimum of 6” away from a pipe joint. Tighten two hex head cone point set bolts until heads bottom out on attachment, ensuring proper torque has been applied. | Ordering: Specify figure number, brace pipe size, and sprinkler pipe size. | Note: (This product is not compatible with metric pipe.) For metric piping see Fig. 010, Fig. 031, or Fig. 040. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG015 4in (1.53 lbs, varilla 1in asumida -- alt 1-1/4in da 1.70 lbs) + FIG030 (1.46 lbs) = 2.99 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 12 y 15.', 2.99, 1.36, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SALPHD003', 'SOP ANTIS LONG 3" PHD FIG 031- 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 4413.0, 0.831237192675545, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron and carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada and Factory Mutual approved. Listed for use with PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance.  Versatile design allows for attachment at any angle and the ability to be used in a lateral or longitudinal bracing configuration.  The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting and joined together with a bracing element form a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '3"', NULL, 'Size: Pipe sizes 2” thru 8”. Can use 1” thru 2” SCH 40 pipe, structural steel, and PHD 12 gauge strut channel (1001 & 1201) as sway bracing elements. | Install: Place attachment around pipe to be braced, positioning brace attachment as needed, then tighten clamping bolts and nuts finger tight.  Insert brace component into fitting against back of jaw.  Tighten set screw finger tight, adjust brace angle as needed, then tighten set screw until hex head breaks off.  Then evenly torque clamping bolts until hex portion of clamping nuts break off. | Ordering: Specify figure number and sprinkler pipe size. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG031 3in (3.00 lbs, sin ambiguedad) + FIG030 (1.46 lbs) = 4.46 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 13 y 15.', 4.46, 2.02, NULL, NULL, NULL, NULL, NULL);
