INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('28DETKIDIO', 'DETECTOR HUMO IONICO 4" CON BATERIA 9V KIDDE 0914E', 'KIDDE', 'KIDDE', 'DETECCION', 7365.0, 0.7272988249087317, '', false, '2026-08-04 15:14:44.141571+00', 'Plástico (carcasa electrónica)', NULL, NULL, NULL, '4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', 0.49, 0.222, 'W: 4" (101.6mm) | D: 2" (50.8mm) | H: 4" (101.6mm)', 'kidde.com, PDS_10SDR.pdf (Technical Specifications) -- modelo sucesor 10SDR, nuestro código es el 0914E discontinuado (ver README, sección KIDDE)', 524.5, 'Caja real: W×D×H = 4"×2"×4" = 101.6×50.8×101.6 mm, publicado directo por el fabricante (no es una caja envolvente aproximada).', 'alta (dimensiones exactas del producto, publicadas por el fabricante)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('25EXHDFSP4', 'RESTRICTORES - TUF GRIP (HEXAGONAL) HD 4" (CON KIT EMP. TORN) PVCPK4004 STAR PIPE - 6990024283', 'STAR PIPE', 'RELIABLE', 'C900', 3572.0, 0.8507809387999817, 'starpipeproducts.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado en nombre del producto (PVC Stargrip, starpipeproducts.com) | CORRECCIÓN: material antes puesto como "PVC" por el nombre del producto -- la ficha real aclara que "PVC" describe el tipo de tubería para la que sirve, no el material de la pieza. El gland/cuñas son de hierro dúctil.', 9, 4.08, 'ØA: 4.93" (125.2mm) | B: 9.12" (231.6mm) | C1: 9.53" (242.1mm)', 'starpipeproducts.com, 4000_SubmittalHD_2401.pdf (tabla "PVC STARGRIP 4000HD SPECIFICATIONS", talla 4")', 7020.01, 'Caja envolvente: B × C1 × ØA (diámetro base como profundidad) = 231.6×242.1×125.2 mm. Mismo tipo de pieza que Tyler Union (collar alrededor de tubería) -- misma lógica de caja envolvente.', 'media (3 ejes de ficha real, pero forma de anillo hueco -- la caja es una sobrestimación intencional)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A10000112', 'SOPORTE TIPO PERA-FIG 100 UL/FM 1-1/2" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 26260.5, 0.5120033376041524, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', NULL, 'EG', 'Conforms WW-H-171 Type 10, ANSI/MSS-SP-58 Type 10', NULL, '1-1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'H: 3-13/16" | CL: 1-3/4" | RS: 3/8" | A: 1-13/16" | Max. Rec. Load: 300 lbs', 'erico.com (ficha original Ferguson, ver README)', 89.28, 'Caja envolvente aproximada: (E o H)×(E o H)×RodSize = 96.84×96.84×9.52 mm. La altura total (E en PHD, H en ERICO) se usa también como ancho porque la pieza es un aro redondo. NO se encontró dato de profundidad/grosor de banda en ninguna fuente pública -- se usa Rod Size (el diámetro de la varilla, el dato más chico disponible) como aproximación conservadora de esa profundidad faltante. Es un supuesto explícito, no un dato confirmado.', 'baja (falta eje de profundidad, aproximado con Rod Size)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A10000114', 'SOPORTE TIPO PERA-FIG 100 UL/FM  1-1/4" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 29051.0, 0.4638119936101973, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', NULL, 'EG', 'Conforms WW-H-171 Type 10, ANSI/MSS-SP-58 Type 10', NULL, '1-1/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'H: 3-9/16" | CL: 1-5/8" | RS: 3/8" | A: 1-13/16" | Max. Rec. Load: 300 lbs', 'erico.com (ficha original Ferguson, ver README)', 77.95, 'Caja envolvente aproximada: (E o H)×(E o H)×RodSize = 90.49×90.49×9.52 mm. La altura total (E en PHD, H en ERICO) se usa también como ancho porque la pieza es un aro redondo. NO se encontró dato de profundidad/grosor de banda en ninguna fuente pública -- se usa Rod Size (el diámetro de la varilla, el dato más chico disponible) como aproximación conservadora de esa profundidad faltante. Es un supuesto explícito, no un dato confirmado.', 'baja (falta eje de profundidad, aproximado con Rod Size)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0212', 'SOPORTE TIPO PERA FIG 141 2 1/2" PHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 42164.0, 0.3667404306956918, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '1/2"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7A1EDCRR12', 'ESCUDO DOBLE CROMADO 1/2". GF2C - 6800800000 RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 26411.0, 0.4985149663467658, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Acero al carbono (mild steel); disponible tambien en acero inoxidable', 'Cromado', NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en fichas de escudos/accesorios', NULL, NULL, 'Diametro 2-7/8" (73mm) x profundidad 7/8" (22mm) - Escudo recessed Modelo F2 (dos piezas, ajuste vertical 1/2" / 12mm)', 'reliablesprinkler.com, Bulletin 204 (Escutcheons and Extender Rings), especificaciones Modelo F2, feb 2025', 92.09, 'cilindro envolvente (diametro x profundidad) segun especificacion de catalogo Modelo F2', 'media (modelo F2 confirmado por nombre_producto "MOD G/F2"; dimension tomada de tabla de especificaciones del boletin, no de diagrama acotado con figura)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73A1B2B3', 'TY 313 773701155 UP QR BR K5.6 155°F 68°C 1/2"  TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 4660.0, 0.8219600955595798, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-05: el material anterior venía de TFP110 (Series TY-L, tipo fusible/soldadura) pero este código es Series TY-FRB (tipo bulbo de vidrio) según TFP172 -- son productos físicamente distintos. Material real pendiente de recargar desde TFP172. | Desglose TFP172 (Physical Characteristics, Series TY-FRB): Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Stainless Steel w/TEFLON | Bulb: Glass | Compression Screw: Bronze | Deflector: Bronze.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2" (50.8mm)', 'tyco-fire.com, TFP172.pdf, Figura 1/4/5 -- coincide exacto con SIN TY313/TY323 (no confundir con el 2-7/8"/73mm que es el escudo empotrado, un accesorio aparte)', 130.54, 'Cilindro real: π×(diámetro/2)²×largo = π×(28.6)²×50.8 mm. Pieza redonda de verdad (no abrazadera irregular), diámetro y largo confirmados con diagrama revisado a mano.', 'alta (dimensiones exactas del fabricante para el SIN exacto, verificado con el diagrama)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('75B1B2A2', '518949155 TY5137 UP QR/ CR 155°F 68°C EC K11.2 3/4"', 'TYCO', 'TYCO', 'SPRINKLES', 4198.0, 0.838917224131771, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '3/4"', '11.2', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Physical Characteristics TFP220: Frame: Bronze | Button: Bronze | Sealing Assembly: Beryllium Nickel w/TEFLON | Bulb: Glass (3mm) | Compression Screw: Bronze | Deflector: Brass. || CONFIRMADO 2026-08-11: ficha TFP181 -- corregir, ficha correcta es TFP220 (Series EC-11/EC-14), confirmada exacta para SIN TY5137 via "Technical Data Sheet: TFP220" en el Price Book Section 2. Figura 1 solo acota alturas (2-7/16"/61.9mm total upright/pendent, 1-11/16"/42.7mm cuerpo, 1/2"/12.7mm nominal make-in) -- no hay diametro/ancho del cuerpo en ningun diagrama de la ficha (a diferencia de TY3331, que si tenia ancho de deflector). Mismo tipo de vacio que ERICO FIG300/310. Sin volumen.', NULL, NULL, 'Largo (Upright y Pendent): 2-7/16" (61.9mm) | Nominal Make-In: 1/2" (12.7mm)', 'tyco-fire.com, TFP220.pdf, Figura 1 (Series EC-11) -- sin diámetro de cuerpo publicado en la ficha', NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDQRCR12', '773719155 TY323 PD QR CR K5.6 155°F 68°C 1/2" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 65489.0, 0.2345208469363032, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-05: el material anterior venía de TFP110 (Series TY-L, tipo fusible/soldadura) pero este código es Series TY-FRB (tipo bulbo de vidrio) según TFP172 -- son productos físicamente distintos. Material real pendiente de recargar desde TFP172. | Desglose TFP172 (Physical Characteristics, Series TY-FRB): Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Stainless Steel w/TEFLON | Bulb: Glass | Compression Screw: Bronze | Deflector: Bronze.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2" (50.8mm)', 'tyco-fire.com, TFP172.pdf, Figura 1/4/5 -- coincide exacto con SIN TY313/TY323 (no confundir con el 2-7/8"/73mm que es el escudo empotrado, un accesorio aparte)', 130.54, 'Cilindro real: π×(diámetro/2)²×largo = π×(28.6)²×50.8 mm. Pieza redonda de verdad (no abrazadera irregular), diámetro y largo confirmados con diagrama revisado a mano.', 'alta (dimensiones exactas del fabricante para el SIN exacto, verificado con el diagrama)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDSRCR12', '775719155 TY325 PD SR CR K5.6 155°F 68°C 1/2" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 26427.0, 0.4917363241387522, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-10: material anterior venía de TFP110 (Series TY-L) por error -- este código es Series TY-B (bulbo de vidrio 5mm) según TFP152, documento distinto. Desglose TFP152: Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Stainless Steel w/TEFLON | Bulb: Glass.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2" (50.8mm)', 'tyco-fire.com, TFP152.pdf, Figura 1 -- coincide exacto con SIN TY315/TY325', 130.54, 'Cilindro real: π×(28.6)²×50.8 mm. Mismas dimensiones que TY313/TY323 (misma familia de cuerpo, distinto bulbo 5mm vs 3mm).', 'alta (dimensiones exactas del fabricante para el SIN exacto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('SI40989714', '4098-9714 SENSOR DE HUMO FOTOELECTRICO - SIMPLEX', 'SIMPLEX', 'SIMPLEX', 'DETECCION', 11403.0, 0.6439794795349733, 'johnsoncontrols.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.10, 0.045, '4" (101.6mm) x 4" (101.6mm) x 1" (25.4mm)', 'lifesafetycom.com (distribuidor, no el fabricante directo) -- consistente en dos secciones de la misma página', 262.3, 'Caja real: 4"×4"×1" = 101.6×101.6×25.4 mm, publicado por distribuidor técnico (no encontrado en ficha oficial de Simplex/JCI).', 'media (fuente es distribuidor, no el fabricante; pero consistente en 2 lugares de la misma página)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('78C7C4B3', ' TY9226 PD QR BR ESFR-25 K25 165°F 74°C 1" 584411165', 'TYCO', 'TYCO', 'SPRINKLES', 14183.5, 0.6014334963636437, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass) - Frame', NULL, NULL, NULL, '1"', '25', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Physical Characteristics TFP312: Frame: Brass | Deflector: Bronze | Compression Screw: Stainless Steel | Hook: Monel | Strut: Monel | Link Assembly: Solder, Nickel | Ejection Spring: Inconel.', NULL, NULL, 'Largo total: 3-13/16" (96.8mm) | Ancho deflector (punto más ancho): 2" (50.8mm) | Nominal Make-In: 9/16" (14.3mm)', 'tyco-fire.com, TFP312.pdf, Figura 1 (Model ESFR-25, K=25.2)', 196.2, 'Cilindro aproximado: π×(25.4)²×96.8 mm, usando el ancho del deflector (el punto más ancho) como diámetro. El deflector real es tipo abanico, no un disco perfecto, así que esto es una sobrestimación leve intencional.', 'media (dimensiones exactas del fabricante, pero forma real del deflector no es un cilindro perfecto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B31002112', 'TE MEC SAL RAN UL/FM  2 " X 1-1/2". P3G 60X48 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 7455.0, 0.723500516399535, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Talla 2x1-1/2: medidas (116, 76, 69.5) mm (ver volumen_metodo)', 'Ficha PDF real (botón Download) fu-mech.com/product/mech-grooved-mech-tee-grvd-model-3g/. Tabla ''3G'', columnas Nominal Size/Pipe O.D./Hole Dia/Dimensions A,B,C,D/Bolt Size.', 612.71, 'Caja envolvente real: A×B×C = 116×76×69.5 mm, tabla oficial UL/FM por talla nominal.', 'alta (3 ejes reales de tabla oficial del fabricante, sin supuestos)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6D4PHD1012', 'BEAM CLAMP FIG 360 1/2" PHD (FIG 310)', 'PHD', 'RELIABLE', 'SOPORTERIA', 13762.0, 0.6085445130239452, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron with hardened steel cup point set screw and locknut', 'Plain or electro-galvanized', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), and Factory Mutual Approved for rod sizes 3/8” and 1/2” only. Complies with Federal Specifications A-A-1192A (Type 19) and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 19) which supersedes ANSI/MSS SP-69. (Approvals are only valid for beam clamps with locknut).', 'Designed for attaching hanger rod to the top flange of a beam or bar joist, where the flange thickness does not exceed 11/4” (31.75mm). The open U design permits rod adjustment.', '1/2"', NULL, 'Ordering: Specify figure number, rod size, and finish. | Note: When a torque wrench is unavailable, the setscrew should be tightened so it contacts the I-beam and then an additional 1/4  to 1/2 turn. | Tamaño derivado del propio código interno, no de ficha del fabricante', 0.35, 0.16, 'Rod Size A: 1/2 | B: 1 (25.40mm) | C: 1-7/8 (47.63mm) | D: 1-5/8 (41.28mm) | E: 1/2 (12.70mm) | Max. Pipe Size: 8 | Max. Rec. Load: 500 lbs (2.22kN)', 'https://www.phd-mfg.com/wp-content/uploads/2025/12/360_11-12-25.pdf', 49.94, 'Caja envolvente: D×C×B = 41.28×47.63×25.4 mm, tomado de una ficha con 2 vistas reales (frontal: D=alcance de la mordaza, C=altura; lateral: B=ancho de la base). Las 3 medidas vienen del dibujo técnico, no son un supuesto.', 'media (3 ejes de un dibujo real de 2 vistas)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0002', 'SOPORTE TIPO PERA FIG 141 2" PHD - 2HPHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 75492.0, 0.2007554524809764, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '2"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0003', 'SOPORTE TIPO PERA FIG 141 3" PHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 37478.0, 0.4074941584227535, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '3"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0004', 'SOPORTE TIPO PERA FIG 141 4" PHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 44571.0, 0.3335727969348659, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '4"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('VTAEXTGF2C', 'ESCUDO DOBLE CROMADO 1/2" MOD. F2 - RASCO RELIABLE. GF2C (VTA.  EXT)', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 5000.0, 0.8146658237958547, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Acero al carbono (mild steel); disponible tambien en acero inoxidable', 'Cromado', NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en fichas de escudos/accesorios', NULL, NULL, 'Diametro 2-7/8" (73mm) x profundidad 7/8" (22mm) - Escudo recessed Modelo F2 (dos piezas, ajuste vertical 1/2" / 12mm)', 'reliablesprinkler.com, Bulletin 204 (Escutcheons and Extender Rings), especificaciones Modelo F2, feb 2025', 92.09, 'cilindro envolvente (diametro x profundidad) segun especificacion de catalogo Modelo F2', 'media (modelo F2 confirmado por nombre_producto "MOD G/F2"; dimension tomada de tabla de especificaciones del boletin, no de diagrama acotado con figura)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SATPHD003', 'SOP ANTIS TRANSV  3" PHD  FIG. 015 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 5310.0, 0.80545763983853, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada (21/2” thru 6” only) and Factory Mutual approved. Listed for use with NFPA and PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance. The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting, and joined together with a bracing pipe element forms a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '3"', NULL, 'Size: Pipe size 21/2” thru 8”. | Install: Place over the pipe to be braced, adjust brace angle, and insert bracing pipe through opening leaving a minimum of 1” extending from attachment. Brace pipe can be installed on top or bottom of pipe to be braced but must be a minimum of 6” away from a pipe joint. Tighten two hex head cone point set bolts until heads bottom out on attachment, ensuring proper torque has been applied. | Ordering: Specify figure number, brace pipe size, and sprinkler pipe size. | Note: (This product is not compatible with metric pipe.) For metric piping see Fig. 010, Fig. 031, or Fig. 040. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG015 3in (1.40 lbs, varilla 1in asumida -- alt 1-1/4in da 1.57 lbs) + FIG030 (1.46 lbs) = 2.86 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 12 y 15.', 2.86, 1.30, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SALPHD006', 'SOP ANTIS LONG 6" PHD FIG 031 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 4741.0, 0.8183619817011821, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron and carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada and Factory Mutual approved. Listed for use with PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance.  Versatile design allows for attachment at any angle and the ability to be used in a lateral or longitudinal bracing configuration.  The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting and joined together with a bracing element form a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '6"', NULL, 'Size: Pipe sizes 2” thru 8”. Can use 1” thru 2” SCH 40 pipe, structural steel, and PHD 12 gauge strut channel (1001 & 1201) as sway bracing elements. | Install: Place attachment around pipe to be braced, positioning brace attachment as needed, then tighten clamping bolts and nuts finger tight.  Insert brace component into fitting against back of jaw.  Tighten set screw finger tight, adjust brace angle as needed, then tighten set screw until hex head breaks off.  Then evenly torque clamping bolts until hex portion of clamping nuts break off. | Ordering: Specify figure number and sprinkler pipe size. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG031 6in (5.42 lbs, sin ambiguedad) + FIG030 (1.46 lbs) = 6.88 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 13 y 15.', 6.88, 3.12, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A20012341', 'SOPORTE TIPO PERA FIG 69 UL/FM 1/2"-1" ANVIL - 12HAN', 'ANVIL', 'RELIABLE', 'SOPORTERIA', 143873.0, 0.03692641665948019, 'anvilintl.com, asc-es.com', true, '2026-08-04 15:14:44.141571+00', 'Acero al carbono (Carbon Steel)', 'Correa pre-galvanizada (zinc); tuerca zincada', 'Federal Spec A-A-1192A (Type 10), WW-H-171-E (Type 10), ANSI/MSS SP-58 (Type 10). UL Listed, FM Approved (1/4"-8")', NULL, '1/2" x 1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Ficha: asc-es.com/resource/69 Adjustable Swivel Ring Submittal (SS-SUB-69-v01). Peso confirmado igual para 1/2", 3/4" y 1" (todo el rango del código); dimensiones A/B/C/F/G varían por tamaño exacto, no se cargaron para evitar desalinear filas.', 0.10, 0.045, 'Talla representativa 3/4" (del rango 1/2"-1" del código): Rod Size A=3/8", B=2-3/4", C=1-7/8", F=15/16", G Width=5/8"', 'asc-es.com, ficha real Submittal SS-SUB-69-v01 (Anvil FIG 69 Adjustable Swivel Ring), tabla completa por talla + diagrama con letras A/B/C/F/G etiquetadas', 10.56, 'Caja envolvente B x G x Rod Size A = 2-3/4" x 5/8" x 3/8" = 69.85 x 15.875 x 9.525 mm, usando las 3 medidas reales de la ficha (B=altura total, G=ancho del aro, Rod Size=proxy de profundidad, mismo patron ya usado en ganchos tipo pera PHD/ERICO). SUPUESTO EXPLICITO: el codigo interno cubre un RANGO de 3 tallas (1/2", 3/4", 1") con volumenes muy similares (9.84-11.04 cm3, ~11% de spread) -- se eligio la talla del medio (3/4") como representante unico, confirmado con el usuario. Es el UNICO codigo de los 194 con esta ambiguedad de rango (verificado con 2 busquedas de patron sobre nombre_producto).', 'baja (representa 1 de 3 tallas posibles dentro de un codigo de rango; la formula en si es media/alta, 2 de 3 ejes reales)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SATPHD006', 'SOP ANTIS TRANSV 6" PHD FIG. 015 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 5601.0, 0.7929568955250847, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada (21/2” thru 6” only) and Factory Mutual approved. Listed for use with NFPA and PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance. The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting, and joined together with a bracing pipe element forms a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '6"', NULL, 'Size: Pipe size 21/2” thru 8”. | Install: Place over the pipe to be braced, adjust brace angle, and insert bracing pipe through opening leaving a minimum of 1” extending from attachment. Brace pipe can be installed on top or bottom of pipe to be braced but must be a minimum of 6” away from a pipe joint. Tighten two hex head cone point set bolts until heads bottom out on attachment, ensuring proper torque has been applied. | Ordering: Specify figure number, brace pipe size, and sprinkler pipe size. | Note: (This product is not compatible with metric pipe.) For metric piping see Fig. 010, Fig. 031, or Fig. 040. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG015 6in (1.81 lbs, varilla 1in asumida -- alt 1-1/4in da 1.98 lbs) + FIG030 (1.46 lbs) = 3.27 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 12 y 15.', 3.27, 1.48, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('42RELEDC34', 'ESCUDO DOBLE CROMADO 3/4 MOD G/F2. GF2LC / 6800880001 RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 10253.5, 0.6634318547675071, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Acero al carbono (mild steel); disponible tambien en acero inoxidable', 'Cromado', NULL, NULL, '3/4', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en fichas de escudos/accesorios', NULL, NULL, 'Diametro 2-7/8" (73mm) x profundidad 7/8" (22mm) - Escudo recessed Modelo F2 (dos piezas, ajuste vertical 1/2" / 12mm)', 'reliablesprinkler.com, Bulletin 204 (Escutcheons and Extender Rings), especificaciones Modelo F2, feb 2025', 92.09, 'cilindro envolvente (diametro x profundidad) segun especificacion de catalogo Modelo F2', 'media (modelo F2 confirmado por nombre_producto "MOD G/F2"; dimension tomada de tabla de especificaciones del boletin, no de diagrama acotado con figura)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('5A28BRSR112', 'VALVULA ANGULAR STDAR 1 1/2" BR HXM. IE25H-M-NST BR - WILSON & COUSINS', 'WILSON & COUSINS', 'WILSON & COUSIN', 'VALVULAS', 4098.0, 0.84103723415177, 'wilsonandcousins.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass)', NULL, NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado en nombre/URL del producto (wilsonandcousins.com)', NULL, NULL, 'A: 4" (100mm) | B: 2-3/4" (69.85mm) | C abierto: 8" (200mm) | C cerrado: 7" (175mm)', 'wilsonandcousins.com, Contractor-Specs-IE25HM-BR-2.pdf', 1222.37, 'Caja envolvente: A×B×C = 100.0×69.85×175.0 mm (cuerpo tipo válvula/boquilla).', 'media (3 medidas de cuerpo de válvula ya publicadas)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A10000002', 'SOPORTE TIPO PERA-FIG 100 UL/FM 2" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 26785.0, 0.4849535753737992, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', NULL, 'EG', 'Conforms WW-H-171 Type 10, ANSI/MSS-SP-58 Type 10', NULL, '2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'H: 4-1/4" | CL: 1-15/16" | RS: 3/8" | A: 1-13/16" | Max. Rec. Load: 300 lbs', 'erico.com (ficha original Ferguson, ver README)', 110.94, 'Caja envolvente aproximada: (E o H)×(E o H)×RodSize = 107.95×107.95×9.52 mm. La altura total (E en PHD, H en ERICO) se usa también como ancho porque la pieza es un aro redondo. NO se encontró dato de profundidad/grosor de banda en ninguna fuente pública -- se usa Rod Size (el diámetro de la varilla, el dato más chico disponible) como aproximación conservadora de esa profundidad faltante. Es un supuesto explícito, no un dato confirmado.', 'baja (falta eje de profundidad, aproximado con Rod Size)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A10000003', 'SOPORTE TIPO PERA-FIG 115 UL/FM 3" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 19858.0, 0.5532891211146836, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', 'Acero (Steel)', 'Pregalvanized (Pregalvanizado)', NULL, NULL, '3"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Catalog 1150300EG | Pipe Size: 3" | OD (diametro del aro): 3 1/2" (88.9mm) | RS (varilla): 3/8" (9.525mm) | A (altura total): 6 9/16" (166.688mm) | B (altura del aro sin collar): 3 1/2" (88.9mm) | C (altura del collar): 1 15/16" (49.212mm)', 'nvent.com/en-us/caddy/products/115-standard-duty-loop-hanger-0/pdf (ficha tecnica real, tabla+diagrama, verificada contra catalogo 1150300EG)', 141.15, 'Caja envolvente: OD x A x RS = 88.9 x 166.688 x 9.525 mm. OD (diametro real del aro) y A (altura total real, de la ficha con diagrama de nVent) son datos confirmados; NO hay dato de profundidad/grosor de banda publicado en ninguna fuente revisada -- se usa Rod Size (RS, el diametro de la varilla) como aproximacion conservadora de esa profundidad faltante, mismo supuesto ya usado en PHD FIG141/ERICO FIG100 (calc_anillo_ganchos), pero aqui con un ancho (OD) real en vez de asumido.', 'media (2 de 3 ejes reales: OD y A de ficha nVent; profundidad aproximada con Rod Size)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000112', 'ACOPLE FLEX RAN UL/FM 1-1/2". P1N 48 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 7951.0, 0.7057001320258053, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'') | Verificado con PDF real (Reducing-Flexible-Coupling1N-2.pdf, descargado tambien manualmente por el usuario, byte-identico): la reduccion "1.5"x1"" (un paso estandar hacia abajo) NO existe como fila en ninguna de las tablas 1N/1NS/1NH -- 1.5" solo aparece como lado CHICO de las combinaciones 2"x1.5" y 2.5"x1.5", nunca como lado grande. No se puede aplicar el mismo supuesto que a 2"/3"/4"/2.5" sin inventar una combinacion inexistente. Queda sin volumen.', NULL, NULL, 'Tabla "1N Standard Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.13, fila 40mm/1½": A=70mm, B=110mm, C=44mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf, pag.13, tabla 1N -- esta fila estaba corrupta/superpuesta en el recorte individual (ficha_real_red-coupling-model-1n.pdf) y no se pudo leer con certeza; el catalogo maestro completo si la trae limpia', 338.80, 'Caja envolvente real A x B x C = 70 x 110 x 44 mm, lectura directa y limpia del catalogo maestro completo.', 'alta (fila real limpia del catalogo maestro completo, coincide exacto con la talla del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3A20000114', 'ACOPLE FLEX RAN UL/FM  1-1/4". P1N 42 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 5683.0, 0.7886233229848096, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'') | Verificado con PDF real (Reducing-Flexible-Coupling1N-2.pdf, descargado tambien manualmente por el usuario, byte-identico): la talla 1-1/4" (42mm) no aparece en NINGUNA fila de ninguna tabla de acoples reductores 1N/1NS/1NH -- el modelo 1N no se fabrica en esa talla. Queda sin volumen.', NULL, NULL, 'Tabla "1N Standard Flexible Coupling" (no reductora), catalogo maestro MECH-GROOVED-NEW-.pdf pag.13, fila 32mm/1¼": A=65mm, B=104mm, C=44mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf, pag.13, tabla 1N -- confirma exacto el valor ya cargado desde texto oculto de un recorte individual, ahora con fuente limpia adicional', 297.44, 'Caja envolvente real A x B x C = 65 x 104 x 44 mm, confirmado en 2 fuentes (texto oculto de recorte individual + catalogo maestro completo, valores identicos).', 'alta (confirmado en 2 fuentes reales, sin ambiguedad)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6E1TCH0038', 'VARILLA ROS GALV 3/8" X 3MTS TANDL CH', 'TANDL', 'TANDL', 'ACCESORIOS', 4633.0, 0.8243413852648522, '', false, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '3/8"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73USRBRR12', 'RA1325 UP. STD. BRONCE K5.6 155°F 68°C 1/2" MOD. F156 / F56U1BN - RASCO RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 6120.5, 0.7736111624430726, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 5mm (standard response)', 'Bronce', NULL, NULL, '1/2"', '5.6 (80)', 'Style List: Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm), cuello 1-3/8" (33mm), alto 2-1/4" (58mm) - Modelo F1-56 Upright, Figura 1', 'reliablesprinkler.com, Bulletin 071, SIN RA1325, Figura 1, pagina 2 de 9, septiembre 2025', 313.8, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (58mm) del diagrama acotado (imagen renderizada y verificada)', 'alta (SIN RA1325 verificado contra nombre_producto y K-factor; diagrama acotado renderizado y verificado visualmente)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73USRCRR12', 'RA1325 UP. STD. CROMADO K5.6 155°F 68°C 1/2" MOD. F156 / F56U1C - RASCO RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 5344.0, 0.804094776254245, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 5mm (standard response)', 'Cromado', NULL, NULL, '1/2"', '5.6 (80)', 'Style List: Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm), cuello 1-3/8" (33mm), alto 2-1/4" (58mm) - Modelo F1-56 Upright, Figura 1', 'reliablesprinkler.com, Bulletin 071, SIN RA1325, Figura 1, pagina 2 de 9, septiembre 2025', 313.8, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (58mm) del diagrama acotado (imagen renderizada y verificada)', 'alta (SIN RA1325 verificado contra nombre_producto y K-factor; diagrama acotado renderizado y verificado visualmente)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3E12002122', 'RED CON RAN X RAN UL/FM 2-1/2"  X  2". P240 73X60 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 3958.0, 0.8431048855707908, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '2-1/2" x 2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "240 Grooved Concentric Reducer" del catalogo maestro, fila 2½"x2" (73.0x60.3mm): L=64mm', 'fu-mech.com, catalogo maestro MECH-GROOVED-NEW-.pdf pag.51, tabla 240', 341.06, 'Caja envolvente L x D x D = 64 x 73.0 x 73.0 mm (D=O.D. del lado grande, variante 73.0mm consistente con el resto de familias MECH del proyecto).', 'media (1 eje de longitud real de tabla oficial + O.D. como proxy de ancho/alto, mismo patron ya usado en otras familias MECH)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('74PDQRCR34', 'TY4231 573919155  PD QR CR K8.0 155°F 68°C 3/4" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 6963.5, 0.7438239950228528, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '3/4"', '8.0', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-05: el material anterior venía de TFP110 (Series TY-L, tipo fusible/soldadura) pero este código es Series TY-FRB (tipo bulbo de vidrio) según TFP172 -- son productos físicamente distintos. Material real pendiente de recargar desde TFP172. | Desglose TFP171 (Physical Characteristics, Series TY-FRB 8.0K): Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Beryllium Nickel w/Teflon | Bulb: Glass | Compression Screw: Bronze | Deflector: Copper/Bronze.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2-5/16" (58.7mm)', 'tyco-fire.com, TFP171_alt.pdf (Series TY-FRB 4.2/5.6/8.0K), Figura 3 -- diámetro 57.2mm confirmado consistente en 4 variantes distintas (4.2K y 5.6K a 1/2", 5.6K y 8.0K a 3/4")', 150.84, 'Cilindro real: π×(28.6)²×58.7 mm.', 'alta (diámetro confirmado por consistencia cruzada entre 4 fichas del mismo fabricante, largo exacto del SIN correcto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('74UPQRCR34', 'TY4131 573909155 UP QR CR K8.0 155°F 68°C 3/4" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 7810.0, 0.7117493470574464, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Bronce (Bronze) - Frame', NULL, NULL, NULL, '3/4"', '8.0', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Desglose TFP110 (Physical Characteristics): Frame: Brass | Sealing Button: Bronze w/TEFLON | Ejection Spring: Stainless Steel | Strut: MONEL | Hook: Bronze/MONEL | Deflector: Bronze | Fusible Element: Solder, Copper, Stainless Steel. Aplicado a toda la familia TY-L estándar (no varía entre QR/SR, solo cambia el elemento fusible), no a sidewall/oculto/ESFR. | CORRECCIÓN 2026-08-05: el material anterior venía de TFP110 (Series TY-L, tipo fusible/soldadura) pero este código es Series TY-FRB (tipo bulbo de vidrio) según TFP172 -- son productos físicamente distintos. Material real pendiente de recargar desde TFP172. | Desglose TFP171 (Physical Characteristics, Series TY-FRB 8.0K): Frame: Bronze | Button: Brass/Copper | Sealing Assembly: Beryllium Nickel w/Teflon | Bulb: Glass | Compression Screw: Bronze | Deflector: Copper/Bronze.', NULL, NULL, 'Diámetro (cuerpo, sin escudo): 2-1/4" (57.2mm) | Largo (Nominal Make-In): 2-5/16" (58.7mm)', 'tyco-fire.com, TFP171_alt.pdf (Series TY-FRB 4.2/5.6/8.0K), Figura 3 -- diámetro 57.2mm confirmado consistente en 4 variantes distintas (4.2K y 5.6K a 1/2", 5.6K y 8.0K a 3/4")', 150.84, 'Cilindro real: π×(28.6)²×58.7 mm.', 'alta (diámetro confirmado por consistencia cruzada entre 4 fichas del mismo fabricante, largo exacto del SIN correcto)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7A1G000034', 'ESCUDO DOBLE CROMADO USA GLOBE 3/4"', 'GLOBE', 'GLOBE', 'SPRINKLES', 4162.0, 0.8399854422556494, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Acero laminado en frío (Cold Rolled Steel) - material estándar Victaulic para escudos FireLock, acabado cromado (Chrome plated). Opciones de material alternativas del fabricante: Latón o Acero inoxidable -- no se pudo confirmar cuál usa específicamente este SKU histórico GLOBE, se asume el estándar (acero) por ser la opción base.', NULL, NULL, NULL, '3/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado en ficha 40.88.pdf. Accesorio (no es el rociador en sí). Es el escudo compatible con rociadores 3/4" NPT K8.0 (V34 series) según documento 40.88.pdf sección 7.0 y tabla de llaves en 41.01/41.51. Nota: la ficha 40.88.pdf muestra las mismas dimensiones exteriores para V27 y V34 (un solo diagrama combinado), por lo que el volumen es igual al de 7A1G000012/7A20000012.', NULL, NULL, 'Diámetro exterior: 2-7/8" (73.03 mm) | Profundidad ajustable: 1-1/8" a 13/16" (28.58 a 20.64 mm) | Espesor base/reborde: 1/8" (3.18 mm)', 'victaulic.com, 40.88.pdf (FireLock Escutcheons Submittal), Sección 4.0 Dimensiones, diagrama "V24, V27 and V34 Recessed Escutcheon" (el diagrama es único para V24/V27/V34, mismas medidas exteriores independiente del tamaño de rosca del rociador que aloja). Identificación como escudo tipo "Recessed" por coincidir con "ESCUDO DOBLE"; V34 = para rociadores 3/4" NPT (K8.0) según tabla de llaves de instalación en 41.01.pdf/41.51.pdf.', 119.72, 'Cilindro envolvente (espacio de bodega): π×(diámetro/2)²×profundidad_máxima = π×(36.515mm)²×28.58mm = 119,717 mm³', 'media (dimensiones exactas del fabricante Victaulic para el escudo Recessed V27/V34, pero la identificación de "ESCUDO DOBLE" GLOBE = escudo tipo Recessed [vs Flush] es una inferencia razonable por diseño, no confirmada contra catálogo histórico Globe pre-2018)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7A20000012', 'ESCUDO DOBLE BLANCO 1/2" GLOBE', 'GLOBE', 'GLOBE', 'SPRINKLES', 12358.0, 0.6320501882856354, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Acero laminado en frío (Cold Rolled Steel) - material estándar Victaulic para escudos FireLock, acabado pintura poliéster blanca (White polyester painted). Opciones de material alternativas del fabricante: Latón o Acero inoxidable -- no se pudo confirmar cuál usa específicamente este SKU histórico GLOBE, se asume el estándar (acero) por ser la opción base.', NULL, NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado en ficha 40.88.pdf. Accesorio (no es el rociador en sí). Es el escudo compatible con rociadores 1/2" NPT K2.8-K5.6 (V27 series) según documento 40.88.pdf sección 7.0 y tabla de llaves en 41.01/41.51. Mismo cuerpo/dimensiones que 7A1G000012, solo cambia el acabado (blanco poliéster vs cromado).', NULL, NULL, 'Diámetro exterior: 2-7/8" (73.03 mm) | Profundidad ajustable: 1-1/8" a 13/16" (28.58 a 20.64 mm) | Espesor base/reborde: 1/8" (3.18 mm)', 'victaulic.com, 40.88.pdf (FireLock Escutcheons Submittal), Sección 4.0 Dimensiones, diagrama "V24, V27 and V34 Recessed Escutcheon" (el diagrama es único para V24/V27/V34, mismas medidas exteriores independiente del tamaño de rosca del rociador que aloja). Identificación como escudo tipo "Recessed" por coincidir con "ESCUDO DOBLE"; V27 = para rociadores 1/2" NPT (K2.8-K5.6) según tabla de llaves de instalación en 41.01.pdf/41.51.pdf.', 119.72, 'Cilindro envolvente (espacio de bodega): π×(diámetro/2)²×profundidad_máxima = π×(36.515mm)²×28.58mm = 119,717 mm³', 'media (dimensiones exactas del fabricante Victaulic para el escudo Recessed V27/V34, pero la identificación de "ESCUDO DOBLE" GLOBE = escudo tipo Recessed [vs Flush] es una inferencia razonable por diseño, no confirmada contra catálogo histórico Globe pre-2018)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B33001141', 'STRAP (TEE MEC) UL/FM  1-1/4" X 1". P3L 42X34 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 58508.0, 0.2823766082303614, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/4" x 1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Modelo 3L/MT1, 1¼"x1" (32X25): A=57.7mm, B=88.9mm, C=57.2mm', 'meide.mx, ficha individual DS-400-MT1-01-E (U-Bolt Mechanical Tee), pag.4', 293.40, 'Caja envolvente real A x B x C = 57.7 x 88.9 x 57.2 mm.', 'alta (tabla A/B/C real y completa de ficha individual del fabricante, coincide exacto con la combinacion del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B33002114', 'STRAP  (TEE MEC) UL/FM  2" X 1-1/4". P3L 60X42 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 3704.0, 0.848005162968712, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '2" x 1-1/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Modelo 3L/MT1, 2"x1¼" (50X32): A=66.6mm, B=120mm, C=76mm', 'meide.mx, ficha individual DS-400-MT1-01-E (U-Bolt Mechanical Tee), pag.4 (fila con formato ligeramente distinto a las demas, B/C verificados contra su equivalente en pulgadas: 120mm=4.72in, 76mm=2.99in aprox 3in)', 607.39, 'Caja envolvente real A x B x C = 66.6 x 120 x 76 mm.', 'alta (tabla A/B/C real de ficha individual del fabricante, coincide exacto con la combinacion del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7AUPBRSR12', 'GL5661 UP SR BR 1/2" K5.6 155°F 68°', 'GLOBE', 'GLOBE', 'SPRINKLES', 5097.0, 0.8107977038186872, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass) - Frame | Bronce (Bronze) - Deflector, Load Screw, Pip Cap | Resorte/sello: aleación Berilio-Níquel recubierta PTFE | Resorte de alojamiento: Acero inoxidable | Bulbo: vidrio con glicerina 5.0mm (Standard Response) | Llave instalación: hierro dúctil', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Peso no publicado en ninguna ficha Victaulic revisada (41.51, 40.10, 40.88). SIN Victaulic = V2703, re-designación GLOBE = GL5661 (confirmado en submittal 41.51.pdf). Mismo cuerpo/dimensiones que la versión QR (V2704/GL5615); difieren en diámetro de bulbo (5.0mm SR vs 3.0mm QR).', NULL, NULL, 'Diámetro deflector: 1-7/16" (37 mm) | Largo total: 2-3/8" (60 mm) | Nominal make-in (rosca): 7/16" (11 mm)', 'victaulic.com, 41.51.pdf (FireLock Series FL-SR Sprinklers Submittal), Sección 3.0 Especificaciones-Material (pág.6), diagrama rotulado "V2703". SIN V2703 verificado exacto: EQUIVALENT=GL5661 en pág.1 (tabla Standard Response Upright Sprinklers), coincide con "GL5661 UP SR BR K5.6" del nombre_producto. Cruce de verificación con 40.10.pdf pág.4 diagrama "Standard Upright with/without standard V9 coupling - V2703, V2704" (mismas medidas 37mm/60mm).', 64.51, 'Cilindro real (envolvente para espacio de bodega): π×(diámetro/2)²×largo = π×(18.5mm)²×60mm = 64,513 mm³', 'alta (dimensiones exactas del fabricante para el SIN exacto V2703, verificado con diagrama y cruzado con segundo documento)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7AUPCRSR12', 'GL5661 UP SR CR K 5.6 155°F 68° 1/2"', 'GLOBE', 'GLOBE', 'SPRINKLES', 5580.0, 0.7943890572577232, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass) cromado (Chrome plated) - Frame | Bronce (Bronze) - Deflector, Load Screw, Pip Cap | Resorte/sello: aleación Berilio-Níquel recubierta PTFE | Resorte de alojamiento: Acero inoxidable | Bulbo: vidrio con glicerina 5.0mm (Standard Response) | Llave instalación: hierro dúctil', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Peso no publicado en ninguna ficha Victaulic revisada (41.51, 40.10, 40.88). SIN Victaulic = V2703, re-designación GLOBE = GL5661. Mismo cuerpo que 7AUPBRSR12, solo cambia acabado (Chrome plated vs Plain brass/Bronze).', NULL, NULL, 'Diámetro deflector: 1-7/16" (37 mm) | Largo total: 2-3/8" (60 mm) | Nominal make-in (rosca): 7/16" (11 mm)', 'victaulic.com, 41.51.pdf (FireLock Series FL-SR Sprinklers Submittal), Sección 3.0 Especificaciones-Material (pág.6), diagrama rotulado "V2703" (mismo cuerpo que 7AUPBRSR12, difiere solo en acabado Chrome plated en vez de Plain brass). SIN V2703 verificado exacto: EQUIVALENT=GL5661 en pág.1, coincide con "GL5661 UP SR CR K5.6" del nombre_producto. Cruce con 40.10.pdf pág.4.', 64.51, 'Cilindro real (envolvente para espacio de bodega): π×(diámetro/2)²×largo = π×(18.5mm)²×60mm = 64,513 mm³', 'alta (dimensiones exactas del fabricante para el SIN exacto V2703, verificado con diagrama y cruzado con segundo documento)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('G42RELEB12', 'ESCUDO DOBLE BLANCO 1/2" MOD. G/F2. GF2W - 6800840000 RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 9433.0, 0.6834138475153275, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Acero al carbono (mild steel); disponible tambien en acero inoxidable', 'Blanco (poliester)', NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en fichas de escudos/accesorios', NULL, NULL, 'Diametro 2-7/8" (73mm) x profundidad 7/8" (22mm) - Escudo recessed Modelo F2 (dos piezas, ajuste vertical 1/2" / 12mm)', 'reliablesprinkler.com, Bulletin 204 (Escutcheons and Extender Rings), especificaciones Modelo F2, feb 2025', 92.09, 'cilindro envolvente (diametro x profundidad) segun especificacion de catalogo Modelo F2', 'media (modelo F2 confirmado por nombre_producto "MOD G/F2"; dimension tomada de tabla de especificaciones del boletin, no de diagrama acotado con figura)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2SPMECH1', 'SOPORTE TIPO PERA 1". PGSD9 34 - MECH', 'MECH', 'JINAN MEIDE', 'SOPORTERIA', 11531.0, 0.6410527877361781, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Talla 1: medidas (84.44, ''3/8"-16UNC'', 9.525) mm (ver volumen_metodo)', 'Ficha PDF real ''Support hanger - Ring hanger'' (Jinan Meide Casting Co.), sección ''2. Size'', modelo GSD9, tabla por talla A/B/C/D (mm) y Nut size.', 67.91, 'Caja envolvente aproximada (mismo método que PHD FIG141/ERICO FIG100 en completar_volumen.py): D×D×RodSize = 84.44×84.44×9.525 mm. D=altura total del aro (tabla ''2. Size'' ficha GSD9), usada también como ancho por ser aro redondo. Sin vista lateral con la profundidad real de la banda -- se aproxima con el diámetro de la varilla/tuerca de sujeción (3/8"-16UNC=9.525mm). Supuesto explícito.', 'baja (falta eje de profundidad, aproximado con diámetro de varilla, igual que PHD/ERICO)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6D10000012', 'UNIVERSAL BEAM-CLAMP-FIG 300 UL/FM 1/2" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 6468.0, 0.7591607018927119, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro fundido (Cast Iron)', NULL, 'Conforms WW-H-171 (Type 23), MSS SP-58 (Type 19 and 23)', NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado en ficha de FIG 310 (misma familia ''Universal Beam Clamp'' que FIG 300) | Ficha tecnica real de nVent (fig 300, catalogo 3000050EG) revisada con diagrama renderizado como imagen (no solo texto): publica Rod Size (RS)=1/2", A (ancho del cuello donde entra la varilla)=1 1/8", y Flange Thickness (FT)=3/4" Max -- este ultimo es la capacidad MAXIMA de espesor de ala que acepta la mordaza, no una medida fija de la pieza. Verificado tambien contra ficha alterna del mismo fabricante (alldataresource.com), mismos 3 valores, sin dato adicional. Falta por completo el eje de altura total del cuerpo y el eje de largo a lo largo de la viga (no estan en ningun diagrama publicado) -- no se calcula volumen para no inventar un eje. Mas vale perder cobertura que meter un dato equivocado.', NULL, NULL, 'Catalog 3000050EG | RS: 1/2" | A: 1 1/8" | FT: 3/4" Max', 'nvent.com/en-us/caddy/products/300-universal-beam-clamp-0/pdf', NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B33011212', 'STRAP  (TEE MEC) UL/FM  1-1/2" X 1/2". P3L 48X21 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 5404.5, 0.7999576767975425, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/2" x 1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Modelo 3L/MT1, 1½"x1/2" (40X15): A=57.7mm, B=88.9mm, C=57.2mm', 'meide.mx, ficha individual DS-400-MT1-01-E (U-Bolt Mechanical Tee), pag.4', 293.40, 'Caja envolvente real A x B x C = 57.7 x 88.9 x 57.2 mm.', 'alta (tabla A/B/C real y completa de ficha individual del fabricante, coincide exacto con la combinacion del codigo interno)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6F1GTCH038', 'CHAZO ROSCA INTERNA GALV 3/8" TANDL CH', 'TANDL', 'TANDL', 'ACCESORIOS', 33031.0, 0.4332938590547526, '', false, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '3/8"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDQBLR12', 'RA1414 PD. QR. BLANCO K5.6 155°F-68°C 1/2" F1FR56P1W. B2158732S9 RASCO RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 4098.0, 0.8420890260478906, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 3mm', 'Blanco (poliester)', NULL, NULL, '1/2"', '5.6 (80)', 'Style List: Concealed Pendent, Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm) x alto 2-1/4" (57mm), base 1" (25mm) - Modelo F1FR56 Pendent, Figura 2', 'reliablesprinkler.com, Bulletin 074 (F1FR56 Series Quick Response Sprinklers), SIN RA1414, Figura 2, pagina 3 de 9, junio 2025', 308.4, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (57mm) del diagrama acotado', 'alta (SIN RA1414 verificado contra nombre_producto y K-factor; diagrama acotado renderizado y verificado visualmente, cruzado con Bulletin 071 equivalente F1-56 que comparte el mismo dibujo)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0006', 'SOPORTE TIPO PERA FIG 141 6" PHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 23995.0, 0.5312446101440167, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '6"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDSCRR12', 'RA1314 PD. STD. CROMADO K5.6 155°F 68°C 1/2" RASCO REL. F156. F56P1C-A2152132S9', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 4645.0, 0.8231522803710684, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 5mm (standard response)', 'Cromado', NULL, NULL, '1/2"', '5.6 (80)', 'Style List: Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm) x alto 2-1/4" (57mm), base 1" (25mm) - Modelo F1-56 Pendent, Figura 2', 'reliablesprinkler.com, Bulletin 071 (F1-56 Series Standard-Response Sprinklers), SIN RA1314, Figura 2, pagina 3 de 9, septiembre 2025', 308.4, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (57mm) del diagrama acotado (imagen renderizada y verificada)', 'alta (SIN RA1314 verificado contra nombre_producto y K-factor; diagrama acotado renderizado y verificado visualmente)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73REUPQC34', 'RA7326 UP. QR/SR. CROMADO K11.2 ECLH/ECOH 155°F 68°C 3/4" MOD. J112 / J112U1C - RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 6243.0, 0.7672571638885806, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Copa (cup): bronce; marco (frame): laton; sello: niquel con PTFE; tornillo de carga: bronce; resorte (kick spring): acero; deflector: laton; sensor termico: ampolla de vidrio', 'Cromado', NULL, NULL, '3/4"', '11.2 (160)', 'Style List: Pendent, Upright | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin | CORRECCION DE FAMILIA: el SIN RA7326 corresponde a J112 Upright (Bulletin 172), no a GL112 (Bulletin 132, SIN R3226) como sugeria la url_fuente original', NULL, NULL, 'Ancho 1-5/8 pulg (41mm) x alto 2-13/16 pulg (71mm) - Modelo J112 Upright SIN RA7326, Figura 3', 'reliablesprinkler.com, Bulletin 172 (Model J112 and JL112 Sprinklers), SIN RA7326, Figura 3, pagina 4 de 7, agosto 2024 -- CORRECCION: la url_fuente registrada en BD apunta a /product/gl112/ (Bulletin 132, GL112, SIN R3226/R3216, sin la letra A), pero el SIN literal (RA7326) y la mencion explicita MOD. J112 en nombre_producto corresponden al Bulletin 172 (J112/JL112), no a GL112. GL112 no aplica a ningun codigo de esta marca.', 93.75, 'cilindro real pi x (diametro/2)^2 x alto, usando ancho (41mm) y alto total (71mm) del diagrama acotado', 'alta (SIN RA7326 verificado contra nombre_producto; se localizo el boletin correcto J112, distinto al de la url_fuente registrada en BD)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3D10000112', 'TAPA RAN UL/FM 1-1/2" P300 48 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 7296.0, 0.731046571435611, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '1-1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Modelo CP, 1½" (40mm, O.D.48.3mm): L=23.5mm', 'meide.mx, ficha individual DS-CP-300-01-E (Cap simple sin agujero), pag.2', 43.06, 'Cilindro real pi x (D/2)^2 x L = pi x 24.15^2 x 23.5 mm.', 'alta (cilindro real, ficha individual del fabricante, tabla limpia y completa)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0008', 'SOPORTE TIPO PERA FIG 141 8" PHD - 8HPHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 5414.0, 0.7985705588613338, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '8"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
