INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2PHD0114', 'SOPORTE TIPO PERA FIG 141 1 1/4" PHD - 125HPHD', 'PHD', 'RELIABLE', 'SOPORTERIA', 64103.0, 0.250973510654462, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Pre-galvanized (Fig. 141) or pre-galvanized with felt lining (Fig. 141F)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), for use with standard steel pipe sizes 3⁄4” (20mm) to 8″ (200mm) and CPVC pipe size 3⁄4” (20mm) to 4″ (100mm). Factory Mutual Approved for steel pipe sizes 3⁄4” (20mm) to 8″ (200mm). Complies with Federal Specifications A-A-1192A (Type 10), and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 10) which supersedes ANSI/MSS SP-69.', 'Designed for the suspension of non-insulated stationary pipe lines. The knurled insert nut that allows a vertical adjustment after installation, is tapped to NFPA reduced rod size standards. Captured knurled insert nut present on pipe sizes 1⁄2” (15mm) to 2″ (50mm). The capture is permanent in the bottom portion of the band, allowing the hanger to be opened during installation if desired, but preventing the knurled insert nut from falling completely out. Fig. 141F has a layer of felt which separates the pipe from the hanger to reduce vibration and sound.', '1/4"', NULL, 'Ordering: Specify figure number and pipe size. | Note: If ordering Fig. 141F felt lined hangers for pipe sizes of 31/2”  (90mm) or under, order the next largest size to allow for the thickness of the felt lining. Metric knurl insert nuts available upon request.
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6D4PHD0038', 'BEAM CLAMP W/LN FIG 363 3/8 PHD (310)', 'PHD', 'RELIABLE', 'SOPORTERIA', 42693.0, 0.355918626520966, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron with hardened steel cup point set screw and locknut', 'Plain or electro-galvanized (Hot dipped galvanized with electro-galvanized hardware upon request)', 'Underwriters’ Laboratories Listed in the U.S. (UL), Canada (CUL), and Factory Mutual Approved for rod sizes. Complies with Federal Specifications A-A-1192A (Type 19) and Manufacturers’ Standardization Society ANSI/MSS SP-58 (Type 19) which supersedes ANSI/MSS SP-69. (Approvals are only valid for beam clamps with locknut). Buy American Act compliant.', 'Designed for attaching hanger rod to the top flange of a beam or bar joist, where the flange thickness does not exceed 11/4” (31.75mm). The open U design permits rod adjustment.', '3/8', NULL, 'Ordering: Specify figure number, rod size, and finish. | Note: When a torque wrench is unavailable, the setscrew should be tightened so it contacts the I-beam and then an additional 1/4  to 1/2 turn. | Tamaño derivado del propio código interno, no de ficha del fabricante', 0.37, 0.17, 'Rod Size A: 3/8 | B: 1 (25.40mm) | C: 1-7/8 (47.63mm) | D: 1-5/8 (41.28mm) | E: 1/2 (12.70mm) | Max. Pipe Size: 4 | Max. Rec. Load: 400 lbs (1.78kN)', 'https://www.phd-mfg.com/wp-content/uploads/2025/12/363364_11-12-25.pdf', 49.94, 'Caja envolvente: D×C×B = 41.28×47.63×25.4 mm, tomado de una ficha con 2 vistas reales (frontal: D=alcance de la mordaza, C=altura; lateral: B=ancho de la base). Las 3 medidas vienen del dibujo técnico, no son un supuesto.', 'media (3 ejes de un dibujo real de 2 vistas)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7APDQRBR12', 'GL5601 PD QR BR K5.6 155°F 68°C 1/2" USA GLOBE', 'GLOBE', 'GLOBE', 'SPRINKLES', 4485.0, 0.827819895652388, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass) - Frame | Bronce (Bronze) - Deflector, Load Screw, Pip Cap | Resorte/sello: aleación Berilio-Níquel recubierta PTFE | Resorte de alojamiento: Acero inoxidable | Bulbo: vidrio con glicerina 3.0mm (Quick Response) | Llave instalación: hierro dúctil', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Peso no publicado en ninguna ficha Victaulic revisada (41.01, 40.10, 40.88). SIN Victaulic = V2708, re-designación/equivalente histórico GLOBE = GL5601 (confirmado en submittal 41.01.pdf).', NULL, NULL, 'Diámetro deflector: 1" (25 mm) | Largo total: 2-3/8" (60 mm) | Nominal make-in (rosca): 7/16" (11 mm)', 'victaulic.com, 40.10.pdf (FireLock K5.6 Models V2703, V2704, V2707, V2708 -- submittal oficial en literatura descontinuada de Victaulic), Sección 4.0 Dimensiones, diagrama "Standard Pendent with/without standard V9 coupling - V2707, V2708". SIN V2708 verificado exacto: EQUIVALENT=GL5601 en 41.01.pdf pág.1 (tabla Quick Response Pendent Sprinklers), coincide con "GL5601 PD QR BR K5.6" del nombre_producto. Cruce de verificación adicional con 41.01.pdf pág.6 diagrama V2762 (modelo EUR-AP "comparable to V2708") que muestra las mismas medidas (25mm/60mm).', 29.45, 'Cilindro real (envolvente para espacio de bodega): π×(diámetro/2)²×largo = π×(12.5mm)²×60mm = 29,452 mm³', 'alta (dimensiones exactas del fabricante para el SIN exacto V2708, verificado con diagrama y cruzado con documento equivalente)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7AUPBR0012', 'GL5615 UP QR BR 1/2" K5.6 155°F 68°', 'GLOBE', 'GLOBE', 'SPRINKLES', 8438.5, 0.6994235164036414, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass) - Frame | Bronce (Bronze) - Deflector, Load Screw, Pip Cap | Resorte/sello: aleación Berilio-Níquel recubierta PTFE | Resorte de alojamiento: Acero inoxidable | Bulbo: vidrio con glicerina 3.0mm (Quick Response) | Llave instalación: hierro dúctil', NULL, NULL, NULL, '1/2"', '5.6', 'Tamaño derivado del propio código interno, no de ficha del fabricante | K-factor derivado del propio código interno | Peso no publicado en ninguna ficha Victaulic revisada (41.01, 40.10, 40.88). SIN Victaulic = V2704, re-designación GLOBE = GL5615 (confirmado en submittal 41.01.pdf).', NULL, NULL, 'Diámetro deflector: 1-7/16" (37 mm) | Largo total: 2-3/8" (60 mm) | Nominal make-in (rosca): 7/16" (11 mm)', 'victaulic.com, 41.01.pdf (FireLock Series FL-QR Sprinklers Submittal), Sección 4.0 Dimensiones (pág.6), diagrama rotulado "V2704". SIN V2704 verificado exacto: EQUIVALENT=GL5615 en pág.1 (tabla Quick Response Upright Sprinklers), coincide con "GL5615 UP QR BR K5.6" del nombre_producto. Cruce de verificación con 40.10.pdf pág.4 diagrama "Standard Upright with/without standard V9 coupling - V2703, V2704" (mismas medidas 37mm/60mm).', 64.51, 'Cilindro real (envolvente para espacio de bodega): π×(diámetro/2)²×largo = π×(18.5mm)²×60mm = 64,513 mm³', 'alta (dimensiones exactas del fabricante para el SIN exacto V2704, verificado con diagrama y cruzado con segundo documento)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('7A1G000012', 'ESCUDO DOBLE CROM 1/2" USA GLOBE', 'GLOBE', 'GLOBE', 'SPRINKLES', 33645.0, 0.4248161289130353, 'victaulic.com', true, '2026-08-04 15:14:44.141571+00', 'Acero laminado en frío (Cold Rolled Steel) - material estándar Victaulic para escudos FireLock, acabado cromado (Chrome plated). Opciones de material alternativas del fabricante: Latón o Acero inoxidable -- no se pudo confirmar cuál usa específicamente este SKU histórico GLOBE, se asume el estándar (acero) por ser la opción base.', NULL, NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado en ficha 40.88.pdf. Accesorio (no es el rociador en sí). Es el escudo compatible con rociadores 1/2" NPT K2.8-K5.6 (V27 series) según documento 40.88.pdf sección 7.0 y tabla de llaves en 41.01/41.51.', NULL, NULL, 'Diámetro exterior: 2-7/8" (73.03 mm) | Profundidad ajustable: 1-1/8" a 13/16" (28.58 a 20.64 mm) | Espesor base/reborde: 1/8" (3.18 mm)', 'victaulic.com, 40.88.pdf (FireLock Escutcheons Submittal), Sección 4.0 Dimensiones, diagrama "V24, V27 and V34 Recessed Escutcheon" (el diagrama es único para V24/V27/V34, mismas medidas exteriores independiente del tamaño de rosca del rociador que aloja). Identificación como escudo tipo "Recessed" (cuerpo copa ajustable + placa) en vez de "Flush" (placa única fija) por coincidir con el nombre "ESCUDO DOBLE" (diseño de dos piezas telescópicas), consistente con V27 = para rociadores 1/2" NPT (K2.8-K5.6) según tabla de llaves de instalación en 41.01.pdf/41.51.pdf.', 119.72, 'Cilindro envolvente (espacio de bodega): π×(diámetro/2)²×profundidad_máxima = π×(36.515mm)²×28.58mm = 119,717 mm³', 'media (dimensiones exactas del fabricante Victaulic para el escudo Recessed V27/V34, pero la identificación de "ESCUDO DOBLE" GLOBE = escudo tipo Recessed [vs Flush] es una inferencia razonable por diseño, no confirmada contra catálogo histórico Globe pre-2018)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3E12002112', 'RED CON RAN X RAN UL/FM 2"  X  1-1/2  MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 5994.0, 0.7766941600653762, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro dúctil (Ductile Iron), ASTM A536 Grade 65-45-12', NULL, NULL, NULL, '2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, MECH-GROOVED-NEW-.pdf pág. 11-12 (sección ''Ductile Iron Grooved Fittings and Couplings'')', NULL, NULL, 'Tabla "240 Grooved Concentric Reducer" (meide.mx DS-400-RC), fila 2"x1½" (60.3x48.3mm): L=64mm', 'meide.mx, ficha individual DS-400-RC-02-E (Grooved Concentric Reducer), pag.3 -- confirma L=64mm, mismo valor ya usado para las otras 4 combinaciones via el catalogo maestro de fu-mech.com (mismo fabricante Jinan Meide, 2 fuentes independientes coinciden)', 232.71, 'Caja envolvente L x D x D = 64 x 60.3 x 60.3 mm (D=O.D. del lado grande), mismo patron que las otras 4 combinaciones del reductor 240 ya cargadas.', 'media (1 eje de longitud real de tabla oficial + O.D. como proxy de ancho/alto, mismo patron ya usado en el resto de la familia; confirmado en 2 fuentes independientes)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('VTAE56P1BN', 'RA1414 PD. QR. BRONCE K5.6 155°F 68°C 1/2" MOD. F1FR56P1BN - RELIABLE (VTA. EXT)', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 9584.0, 0.680992775539704, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 3mm', 'Bronce', NULL, NULL, '1/2"', '5.6 (80)', 'Style List: Concealed Pendent, Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm) x alto 2-1/4" (57mm), base 1" (25mm) - Modelo F1FR56 Pendent, Figura 2', 'reliablesprinkler.com, Bulletin 074 (F1FR56 Series Quick Response Sprinklers), SIN RA1414, Figura 2, pagina 3 de 9, junio 2025', 308.4, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (57mm) del diagrama acotado', 'alta (SIN RA1414 verificado contra nombre_producto y K-factor; diagrama acotado renderizado y verificado visualmente, cruzado con Bulletin 071 equivalente F1-56 que comparte el mismo dibujo)');
