INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A2SPMECH3', 'SOPORTE TIPO PERA 3". PGSD9 89 - MECH', 'MECH', 'JINAN MEIDE', 'SOPORTERIA', 5006.0, 0.8133825247522718, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '3"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Talla 3: medidas (162.74, ''3/8"-16UNC'', 9.525) mm (ver volumen_metodo)', 'Ficha PDF real ''Support hanger - Ring hanger'' (Jinan Meide Casting Co.), sección ''2. Size'', modelo GSD9, tabla por talla A/B/C/D (mm) y Nut size.', 252.26, 'Caja envolvente aproximada (mismo método que PHD FIG141/ERICO FIG100 en completar_volumen.py): D×D×RodSize = 162.74×162.74×9.525 mm. D=altura total del aro (tabla ''2. Size'' ficha GSD9), usada también como ancho por ser aro redondo. Sin vista lateral con la profundidad real de la banda -- se aproxima con el diámetro de la varilla/tuerca de sujeción (3/8"-16UNC=9.525mm). Supuesto explícito.', 'baja (falta eje de profundidad, aproximado con diámetro de varilla, igual que PHD/ERICO)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73UPQRBK34', 'RA6322 UP QR BRONCE K8.0 - 155ºF - 68ºC 3/4" MOD. F1FR80, F1FRU1LBN. B1151134S8 RASCO RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 8421.0, 0.7015848486528438, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 3mm', 'Bronce', NULL, NULL, '3/4"', '8.0 (115)', 'Style List: Pendent, Upright | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin | CORRECCION DE FAMILIA: el SIN RA6322 corresponde a F1FR80 (Bulletin 063), no a F1FR80-300 (Bulletin 078, SIN RA7822) como sugeria la url_fuente original', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm), cuello 1-3/8" (33mm), alto 2-1/2" (62mm) - Modelo F1FR80 Upright SIN RA6322, Figura 1', 'reliablesprinkler.com, Bulletin 063 (F1FR80 Series Quick-Response Sprinklers, 175psi), SIN RA6322, Figura 1, pagina 2 de 6, junio 2025 -- CORRECCION: la url_fuente registrada en BD (scrapes_ultimo) apunta a la pagina f1fr80-300-series-quick-response (Bulletin 078, SIN RA7822, 300psi), pero el SIN literal en nombre_producto (RA6322) corresponde al Bulletin 063 (F1FR80 estandar, 175psi), no a F1FR80-300. Se identifico y descargo la ficha correcta.', 335.4, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (62mm) del diagrama acotado', 'alta (SIN RA6322 verificado contra nombre_producto; se localizo el boletin correcto, distinto al de la url_fuente registrada en BD)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('VTAEXU1LBN', 'RA6322 UP QR BRONCE K8.0 - 155ºF - 68ºC 3/4" MOD. F1FRU1LBN - RELIABLE (VTA. EXT)', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 22600.0, 0.5370451218210114, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Marco (frame): laton; tapa (cap): bronce; arandela de sello: niquel con PTFE; tornillo de carga: cobre; deflector: laton; sensor termico: ampolla de vidrio 3mm', 'Bronce', NULL, NULL, '3/4"', '8.0 (115)', 'Style List: Pendent, Upright | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin | CORRECCION DE FAMILIA: el SIN RA6322 corresponde a F1FR80 (Bulletin 063), no a F1FR80-300 (Bulletin 078, SIN RA7822) como sugeria la url_fuente original', NULL, NULL, 'Ancho (deflector) 3-1/4" (83mm), cuello 1-3/8" (33mm), alto 2-1/2" (62mm) - Modelo F1FR80 Upright SIN RA6322, Figura 1', 'reliablesprinkler.com, Bulletin 063 (F1FR80 Series Quick-Response Sprinklers, 175psi), SIN RA6322, Figura 1, pagina 2 de 6, junio 2025 -- CORRECCION: la url_fuente registrada en BD (scrapes_ultimo) apunta a la pagina f1fr80-300-series-quick-response (Bulletin 078, SIN RA7822, 300psi), pero el SIN literal en nombre_producto (RA6322) corresponde al Bulletin 063 (F1FR80 estandar, 175psi), no a F1FR80-300. Se identifico y descargo la ficha correcta.', 335.4, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del deflector (83mm) y alto total (62mm) del diagrama acotado', 'alta (SIN RA6322 verificado contra nombre_producto; se localizo el boletin correcto, distinto al de la url_fuente registrada en BD)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('42REUPQB34', 'RA7326 UP. QR/SR. BRONCE K11.2 155F° 68C° 3/4 MOD. J112 ECLH / ECOH.  J112U1B / L292114198 - RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 19572.0, 0.5684448828193976, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Copa (cup): bronce; marco (frame): laton; sello: niquel con PTFE; tornillo de carga: bronce; resorte (kick spring): acero; deflector: laton; sensor termico: ampolla de vidrio', 'Bronce', NULL, NULL, '3/4', '11.2 (160)', 'Style List: Pendent, Upright | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin | CORRECCION DE FAMILIA: el SIN RA7326 corresponde a J112 Upright (Bulletin 172), no a GL112 (Bulletin 132, SIN R3226) como sugeria la url_fuente original', NULL, NULL, 'Ancho 1-5/8 pulg (41mm) x alto 2-13/16 pulg (71mm) - Modelo J112 Upright SIN RA7326, Figura 3', 'reliablesprinkler.com, Bulletin 172 (Model J112 and JL112 Sprinklers), SIN RA7326, Figura 3, pagina 4 de 7, agosto 2024 -- CORRECCION: la url_fuente registrada en BD apunta a /product/gl112/ (Bulletin 132, GL112, SIN R3226/R3216, sin la letra A), pero el SIN literal (RA7326) y la mencion explicita MOD. J112 en nombre_producto corresponden al Bulletin 172 (J112/JL112), no a GL112. GL112 no aplica a ningun codigo de esta marca.', 93.75, 'cilindro real pi x (diametro/2)^2 x alto, usando ancho (41mm) y alto total (71mm) del diagrama acotado', 'alta (SIN RA7326 verificado contra nombre_producto; se localizo el boletin correcto J112, distinto al de la url_fuente registrada en BD)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('VTAEX12U1B', 'RA7326 UP. QR/SR. BRONCE K11.2 155F° 68C° 3/4 MOD. J112U1B - L292114198 - RELIABLE (VTA. EXT)', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 10759.0, 0.6553428359060911, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Copa (cup): bronce; marco (frame): laton; sello: niquel con PTFE; tornillo de carga: bronce; resorte (kick spring): acero; deflector: laton; sensor termico: ampolla de vidrio', 'Bronce', NULL, NULL, '3/4', '11.2 (160)', 'Style List: Pendent, Upright | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin | CORRECCION DE FAMILIA: el SIN RA7326 corresponde a J112 Upright (Bulletin 172), no a GL112 (Bulletin 132, SIN R3226) como sugeria la url_fuente original', NULL, NULL, 'Ancho 1-5/8 pulg (41mm) x alto 2-13/16 pulg (71mm) - Modelo J112 Upright SIN RA7326, Figura 3', 'reliablesprinkler.com, Bulletin 172 (Model J112 and JL112 Sprinklers), SIN RA7326, Figura 3, pagina 4 de 7, agosto 2024 -- CORRECCION: la url_fuente registrada en BD apunta a /product/gl112/ (Bulletin 132, GL112, SIN R3226/R3216, sin la letra A), pero el SIN literal (RA7326) y la mencion explicita MOD. J112 en nombre_producto corresponden al Bulletin 172 (J112/JL112), no a GL112. GL112 no aplica a ningun codigo de esta marca.', 93.75, 'cilindro real pi x (diametro/2)^2 x alto, usando ancho (41mm) y alto total (71mm) del diagrama acotado', 'alta (SIN RA7326 verificado contra nombre_producto; se localizo el boletin correcto J112, distinto al de la url_fuente registrada en BD)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDQRCR34', 'RA7216 PD. QR/SR. CROMADO K11.2 155°F-68°C 3/4 MOD. J112 ECOH/ECLH. J112P1C-L272214198 - RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 9204.0, 0.6905736295392851, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Copa (cup): bronce; marco (frame): laton; sello: niquel con PTFE; tornillo de carga: bronce; resorte (kick spring): acero; deflector: laton; sensor termico: ampolla de vidrio', 'Cromado', NULL, NULL, '3/4', '11.2 (160)', 'Style List: Pendent, Upright | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin | CORRECCION DE FAMILIA: el SIN RA7216 corresponde a J112 Pendent (Bulletin 172), no a GL112 (Bulletin 132, SIN R3216) como sugeria la url_fuente original', NULL, NULL, 'Ancho 1-5/8 pulg (42mm) x alto 3 pulg (76mm) - Modelo J112 Pendent SIN RA7216, Figura 1', 'reliablesprinkler.com, Bulletin 172, SIN RA7216, Figura 1, pagina 2 de 7, agosto 2024 -- misma correccion de familia que J112 Upright (url_fuente en BD apunta a GL112, el correcto es J112/Bulletin 172)', 105.29, 'cilindro real pi x (diametro/2)^2 x alto, usando ancho (42mm) y alto total (76mm) del diagrama acotado', 'alta (SIN RA7216 verificado contra nombre_producto; se localizo el boletin correcto J112, distinto al de la url_fuente registrada en BD)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDESFB34', 'RA1914 PD ESFR BRONCE K16.8 - K17, 165ºF-74ºC  3/4" MOD. JL-17 / JL171B. DB16114998 RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 3896.0, 0.8451137618936154, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Sensor termico: eslabon fusible niquel-berilio; marco (frame): laton; tapa (cap): bronce; sello: niquel con PTFE; tornillo de carga: bronce; deflector: bronce; resorte (kick spring): acero inoxidable', 'Bronce', NULL, NULL, '3/4"', '14.0 (200), 16.8 (240)', 'Style List: ESFR Pendent | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Cuello/rosca 1-5/8 pulg (41mm) x alto total 2-13/16 pulg (71mm) - Modelo JL17 ESFR SIN RA1914, Figura 2. NOTA: el diagrama tambien muestra 3-3/4 pulg (95mm), pero esa medida corresponde al diametro del Escudo de Agua Modelo S-3 (accesorio OPCIONAL, se ordena por separado), NO al cuerpo del rociador; se uso 41mm (cuerpo real) para el calculo de volumen, evitando confundir accesorio con cuerpo.', 'reliablesprinkler.com, Bulletin 019 (Model JL14 & JL17 ESFR Pendent Sprinklers), SIN RA1914, Figura 2, pagina 3 de 5, agosto 2024', 93.75, 'cilindro real pi x (diametro/2)^2 x alto, usando diametro del cuerpo (41mm, NO el escudo S-3 opcional de 95mm) y alto total (71mm) del diagrama acotado', 'alta (SIN RA1914 verificado contra nombre_producto y K-factor 16.8; diagrama acotado renderizado y verificado visualmente, se distinguio cuerpo real vs accesorio escudo S-3)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('73PDESFBP1', 'R602 PD. ESFR. BRONCE K25.2 165ºF - 74ºC 1" MOD. P25 COD. P251 / DB16115971- RASCO RELIABLE', 'RELIABLE', 'RELIABLE', 'SPRINKLES', 11943.0, 0.6351154763811375, 'reliablesprinkler.com', true, '2026-08-04 15:14:44.141571+00', 'Sensor termico: eslabon fusible de niquel; marco (frame): laton; tapa (cap): bronce; sello: niquel con PTFE; tornillo de carga: bronce; deflector: bronce; resorte (kick spring): niquel', 'Bronce', NULL, NULL, '1"', '25.2 (360)', 'Style List: Pendent | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso no publicado por el fabricante en este boletin', NULL, NULL, 'Ancho (seccion roscada/hex) 2 pulg (52mm) x alto total 2-7/8 pulg (74mm); rosca 1 pulg NPT - Modelo P25 SIN R602, Figura 1', 'reliablesprinkler.com, Bulletin 070 (Model P25 ESFR Pendent Sprinklers), SIN R602, Figura 1, pagina 2 de 5, junio 2025', 157.15, 'cilindro real pi x (diametro/2)^2 x alto, usando ancho (52mm) y alto total (74mm) del diagrama acotado', 'media-alta (SIN R602 verificado contra nombre_producto y K-factor 25.2; el ancho de 52mm corresponde a la seccion roscada/hexagono acotada en el diagrama, el deflector inferior podria ser marginalmente mas ancho pero el boletin no acota esa medida numericamente)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B32212112', 'TE MEC SAL ROS UL/FM  2-1/2" X 1-1/2". P3J 73X48 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 4661.0, 0.8207640608509605, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', NULL, NULL, NULL, NULL, '2-1/2" x 1-1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Talla 2-1/2x1-1/2: medidas (144, 84.5, 73) mm (ver volumen_metodo)', 'Ficha PDF real (botón Download) fu-mech.com/product/mech-grooved-mech-tee-thd-model-3j/. Tabla ''3J'', columnas Nominal Size/Pipe O.D./Hole Dia/Dimensions A,B,C,D/Bolt Size. Fila 100x65 (4x2-1/2) recuperada de texto embebido fuera del área visible de la página (continuación de la misma tabla en la página siguiente del catálogo original) -- ver nota de la ronda ''revisión MECH thumbnails'' 2026-08-10.', 888.26, 'Caja envolvente real: A×B×C = 144×84.5×73 mm, tabla oficial UL/FM por talla nominal.', 'alta (3 ejes reales de tabla oficial del fabricante, sin supuestos)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SATPHD002', 'SOP ANTIS TRANSV 2" PHD FIG. 010 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 7847.0, 0.7097448339513699, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada and Factory Mutual approved. Listed for use with NFPA and PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance. The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting, and joined together with a bracing pipe element forms a complete sway brace assembly. Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '2"', NULL, 'Size: Pipe size 1” (25) thru 4” (100). | Install: Place over the pipe to be braced, adjust brace angle, and insert bracing pipe through opening leaving a minimum of 1” (25.4) extending from attachment. Brace pipe can be installed on top or bottom of pipe to be braced but must be a minimum of 6” (152.4) away from a pipe joint. Tighten nuts down evenly until hex heads break off. | Ordering: Specify figure number, brace pipe size, and sprinkler pipe size. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG010 (0.84 lbs, varilla de arriostre 1in asumida -- alternativa 1-1/4in da 0.88 lbs) + FIG030 anclaje estructural (1.46 lbs, fijo) = 2.30 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 11 y 15.', 2.30, 1.04, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SATPHD212', 'SOP ANTIS TRANSV 2 1/2" PHD FIG 015 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 9627.0, 0.6785329479329644, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada (21/2” thru 6” only) and Factory Mutual approved. Listed for use with NFPA and PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance. The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting, and joined together with a bracing pipe element forms a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '1/2"', NULL, 'Size: Pipe size 21/2” thru 8”. | Install: Place over the pipe to be braced, adjust brace angle, and insert bracing pipe through opening leaving a minimum of 1” extending from attachment. Brace pipe can be installed on top or bottom of pipe to be braced but must be a minimum of 6” away from a pipe joint. Tighten two hex head cone point set bolts until heads bottom out on attachment, ensuring proper torque has been applied. | Ordering: Specify figure number, brace pipe size, and sprinkler pipe size. | Note: (This product is not compatible with metric pipe.) For metric piping see Fig. 010, Fig. 031, or Fig. 040. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG015 2-1/2in (1.31 lbs, varilla 1in asumida -- alt 1-1/4in da 1.49 lbs) + FIG030 (1.46 lbs) = 2.77 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 12 y 15.', 2.77, 1.26, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SALPHD002', 'SOP ANTIS LONG 2" PHD FIG 031 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 5442.0, 0.7957857999367589, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron and carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada and Factory Mutual approved. Listed for use with PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance.  Versatile design allows for attachment at any angle and the ability to be used in a lateral or longitudinal bracing configuration.  The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting and joined together with a bracing element form a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '2"', NULL, 'Size: Pipe sizes 2” thru 8”. Can use 1” thru 2” SCH 40 pipe, structural steel, and PHD 12 gauge strut channel (1001 & 1201) as sway bracing elements. | Install: Place attachment around pipe to be braced, positioning brace attachment as needed, then tighten clamping bolts and nuts finger tight.  Insert brace component into fitting against back of jaw.  Tighten set screw finger tight, adjust brace angle as needed, then tighten set screw until hex head breaks off.  Then evenly torque clamping bolts until hex portion of clamping nuts break off. | Ordering: Specify figure number and sprinkler pipe size. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG031 2in (2.60 lbs, sin ambiguedad) + FIG030 (1.46 lbs) = 4.06 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 13 y 15.', 4.06, 1.84, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A10000004', 'SOPORTE TIPO PERA-FIG 115 UL/FM 4" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 26217.0, 0.5187321878092749, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', 'Acero (Steel)', 'Pregalvanized (Pregalvanizado)', NULL, NULL, '4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Catalog 1150400EG | Pipe Size: 4" | OD (diametro del aro): 4 1/2" (114.3mm) | RS (varilla): 3/8" (9.525mm) | A (altura total): 7 9/16" (192.087mm) | B (altura del aro sin collar): 4" (101.6mm) | C (altura del collar): 1 15/16" (49.212mm)', 'nvent.com/en-us/caddy/products/115-standard-duty-loop-hanger-0/pdf (ficha tecnica real, tabla+diagrama, verificada contra catalogo 1150400EG)', 209.13, 'Caja envolvente: OD x A x RS = 114.3 x 192.087 x 9.525 mm. OD (diametro real del aro) y A (altura total real, de la ficha con diagrama de nVent) son datos confirmados; NO hay dato de profundidad/grosor de banda publicado en ninguna fuente revisada -- se usa Rod Size (RS, el diametro de la varilla) como aproximacion conservadora de esa profundidad faltante, mismo supuesto ya usado en PHD FIG141/ERICO FIG100 (calc_anillo_ganchos), pero aqui con un ancho (OD) real en vez de asumido.', 'media (2 de 3 ejes reales: OD y A de ficha nVent; profundidad aproximada con Rod Size)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6A10000006', 'SOPORTE TIPO PERA-FIG 115 UL/FM 6" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 12444.0, 0.628878386369516, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', 'Acero (Steel)', 'Pregalvanized (Pregalvanizado)', NULL, NULL, '6"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'Catalog 1150600EG | Pipe Size: 6" | OD (diametro del aro): 6 5/8" (168.275mm) | RS (varilla): 1/2" (12.7mm) | A (altura total): 11 5/16" (287.337mm) | B (altura del aro sin collar): 6 5/16" (160.337mm) | C (altura del collar): 3 5/16" (84.137mm)', 'nvent.com/en-us/caddy/products/115-standard-duty-loop-hanger-0/pdf (ficha tecnica real, tabla+diagrama, verificada contra catalogo 1150600EG)', 614.07, 'Caja envolvente: OD x A x RS = 168.275 x 287.337 x 12.7 mm. OD (diametro real del aro) y A (altura total real, de la ficha con diagrama de nVent) son datos confirmados; NO hay dato de profundidad/grosor de banda publicado en ninguna fuente revisada -- se usa Rod Size (RS, el diametro de la varilla) como aproximacion conservadora de esa profundidad faltante, mismo supuesto ya usado en PHD FIG141/ERICO FIG100 (calc_anillo_ganchos), pero aqui con un ancho (OD) real en vez de asumido.', 'media (2 de 3 ejes reales: OD y A de ficha nVent; profundidad aproximada con Rod Size)');
