INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('6D10000038', 'UNIVERSAL BEAM-CLAMP-FIG 300 UL/FM 3/8" ERICO', 'ERICO', 'LEHMAN', 'SOPORTERIA', 21289.0, 0.5481923706331898, 'erico.com, nvent.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro fundido (Cast Iron)', NULL, 'Conforms WW-H-171 (Type 23), MSS SP-58 (Type 19 and 23)', NULL, '3/8"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado en ficha de FIG 310 (misma familia ''Universal Beam Clamp'' que FIG 300) | Ficha tecnica real de nVent (fig 300, catalogo 3000037EG) revisada con diagrama renderizado como imagen (no solo texto): publica Rod Size (RS)=3/8", A (ancho del cuello donde entra la varilla)=1 1/8", y Flange Thickness (FT)=3/4" Max -- este ultimo es la capacidad MAXIMA de espesor de ala que acepta la mordaza, no una medida fija de la pieza. Verificado tambien contra ficha alterna del mismo fabricante (alldataresource.com), mismos 3 valores, sin dato adicional. Falta por completo el eje de altura total del cuerpo y el eje de largo a lo largo de la viga (no estan en ningun diagrama publicado) -- no se calcula volumen para no inventar un eje. Mas vale perder cobertura que meter un dato equivocado.', NULL, NULL, 'Catalog 3000037EG | RS: 3/8" | A: 1 1/8" | FT: 3/4" Max', 'nvent.com/en-us/caddy/products/300-universal-beam-clamp-0/pdf', NULL, NULL, NULL);
