INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('72ESBLI012', '567924135 ESCUDO BLANCO P/ROC OCULTO INCH 1/2" TYCO', 'TYCO', 'TYCO', 'SPRINKLES', 9927.0, 0.6685763439734221, 'tyco-fire.com, jci.com', true, '2026-08-04 15:14:44.141571+00', 'Latón (Brass)', NULL, NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante', NULL, NULL, 'P/N 56-792-4-135 | Cover Plate (Signal White RAL9003) para rociadores ocultos Series RFII/DS-C/DS-ECC, 150-165F según variante -- mismo P/N y forma física en todas las series que lo usan. | Diametro: 82.6mm | Espesor/profundidad: 4.8mm', 'TFP181 (Series RFII Concealed Pendent Sprinklers) pag.3, Figura 2: ''COVER PLATE DIAMETER DIMENSION A: 3-1/4 in (82,6mm)'' y ''COVER PLATE PROFILE DEPTH DIMENSION B: 3/16 in (4,8mm)'', etiquetas explicitas para el escudo (no el cuerpo del rociador). P/N 56-792-4-135 verificado contra fuentes/tyco_pricebook_2026-01-05.pdf (p.28-29, Cover Plate Signal White).', 25.72, 'Cilindro real: pi x r^2 x h, diametro=82.6mm, altura=4.8mm -- ambas medidas etiquetadas explicitamente en el diagrama de la ficha TFP real (diametro del escudo visible + espesor/profundidad total del ensamble), no un supuesto.', 'alta (diametro y profundidad reales, etiquetados en diagrama de ficha TFP)');
