INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3B1AC00001', 'TEE ACX300 LBS ROSC 1". B130 25 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 19702.0, 0.5634215370431968, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro maleable (Malleable Iron), ASTM A197/A197M', NULL, NULL, NULL, '1"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, BMI-Catalogue-NEW-.pdf pág. 30 (sección ''American Standard Class 300'')', NULL, NULL, 'Talla 1: medidas 38.1 mm (ver volumen_metodo)', 'Ficha PDF real ''Malleable Iron Pipe Fitting American Standard'' (catálogo completo BMI, botón Download de varias páginas de fu-mech.com/product/american-standard-mech-bmi-*), tablas por modelo (90, 90R, 130, 220, 240, 241, 291) con dimensión ''A''/''B'' (mm) por talla + tabla pág. 33 ''Basic Dimension for American Standard Pipe Threads'' (O.D. of Pipe) usada como proxy del diámetro del cuerpo del accesorio.', 96.97, 'Caja envolvente: (2×A)×A×D = 76.2×38.1×33.4 mm. A=dimensión ''center-to-end'' del modelo 130 (BMI, misma tabla que el codo 90 -- estandarizado por ASME B16.3). Se usa 2×A para el largo del ramal recto (se extiende A a cada lado del centro) y A para el alcance de la salida lateral; D=O.D. de tubería como proxy del diámetro del cuerpo.', 'media (A real de catálogo oficial + O.D. de tubería como proxy de profundidad)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3D2AC00012', 'TAPON MACHO ACx300 LBS ROSC. 1/2" MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 33845.0, 0.4161808096487661, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro maleable (Malleable Iron), ASTM A197/A197M', NULL, NULL, NULL, '1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, BMI-Catalogue-NEW-.pdf pág. 30 (sección ''American Standard Class 300'')', NULL, NULL, 'Talla 1/2: medidas 23.9 mm (ver volumen_metodo)', 'Ficha PDF real ''Malleable Iron Pipe Fitting American Standard'' (catálogo completo BMI, botón Download de varias páginas de fu-mech.com/product/american-standard-mech-bmi-*), tablas por modelo (90, 90R, 130, 220, 240, 241, 291) con dimensión ''A''/''B'' (mm) por talla + tabla pág. 33 ''Basic Dimension for American Standard Pipe Threads'' (O.D. of Pipe) usada como proxy del diámetro del cuerpo del accesorio.', 8.55, 'Cilindro real: π×(D/2)²×A = π×(21.34/2)²×23.9 mm. Pieza genuinamente axisimétrica (tapón macho roscado, modelo 291/291S -- mismos valores de A en ambas variantes para esta talla). D=O.D. de tubería (proxy del cuerpo roscado; subestima levemente porque no incluye la cabeza hex/cuadrada de maniobra, más ancha que el diámetro de rosca). A=longitud total de tabla oficial.', 'media (axisimétrico, D aproximado con O.D. de tubería -- subestima la cabeza de maniobra)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3D2AC00034', 'TAPON MACHO ACx300 LBS ROSC. 3/4" MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 6311.0, 0.7624343977528918, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro maleable (Malleable Iron), ASTM A197/A197M', NULL, NULL, NULL, '3/4"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, BMI-Catalogue-NEW-.pdf pág. 30 (sección ''American Standard Class 300'')', NULL, NULL, 'Talla 3/4: medidas 27.2 mm (ver volumen_metodo)', 'Ficha PDF real ''Malleable Iron Pipe Fitting American Standard'' (catálogo completo BMI, botón Download de varias páginas de fu-mech.com/product/american-standard-mech-bmi-*), tablas por modelo (90, 90R, 130, 220, 240, 241, 291) con dimensión ''A''/''B'' (mm) por talla + tabla pág. 33 ''Basic Dimension for American Standard Pipe Threads'' (O.D. of Pipe) usada como proxy del diámetro del cuerpo del accesorio.', 15.2, 'Cilindro real: π×(D/2)²×A = π×(26.67/2)²×27.2 mm. Pieza genuinamente axisimétrica (tapón macho roscado, modelo 291/291S -- mismos valores de A en ambas variantes para esta talla). D=O.D. de tubería (proxy del cuerpo roscado; subestima levemente porque no incluye la cabeza hex/cuadrada de maniobra, más ancha que el diámetro de rosca). A=longitud total de tabla oficial.', 'media (axisimétrico, D aproximado con O.D. de tubería -- subestima la cabeza de maniobra)');
