INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3FAC000112', 'RED BUSHING ACx300 LBS ROSC. 1"x1/2" MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 29656.0, 0.448883889155815, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Hierro maleable (Malleable Iron), ASTM A197/A197M', NULL, NULL, NULL, '1" x 1/2"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por: fu-mech.com, BMI-Catalogue-NEW-.pdf pág. 30 (sección ''American Standard Class 300'')', NULL, NULL, 'Talla 1x1/2: medidas (25.5, ''1'') mm (ver volumen_metodo)', 'Ficha PDF real ''Malleable Iron Pipe Fitting American Standard'' (catálogo completo BMI, botón Download de varias páginas de fu-mech.com/product/american-standard-mech-bmi-*), tablas por modelo (90, 90R, 130, 220, 240, 241, 291) con dimensión ''A''/''B'' (mm) por talla + tabla pág. 33 ''Basic Dimension for American Standard Pipe Threads'' (O.D. of Pipe) usada como proxy del diámetro del cuerpo del accesorio.', 22.34, 'Cilindro real: π×(D/2)²×A = π×(33.4/2)²×25.5 mm. Bushing reductor (modelo 241, exterior roscado talla 1"), tratado como axisimétrico usando el O.D. de tubería del lado MAYOR (roscado exterior) como diámetro y A=altura de tabla oficial. Subestima porque el exterior real es hexagonal (ancho entre caras > O.D. de tubería), no se publica esa medida.', 'media (axisimétrico aproximado, subestima por exterior hexagonal no publicado)');
