INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('1B1MFRM012', 'MANGUERA FLEX. P/ROC 1/2" X 48" TRENZADA C/ACC. EFB48 25X15X441 - MECH', 'MECH', 'JINAN MEIDE', 'ACCESORIOS', 4219.0, 0.8378397662547789, 'meidegroup.com, fu-mech.com', true, '2026-08-04 15:14:44.141571+00', 'Acero inoxidable (Stainless Steel)', NULL, NULL, NULL, '1/2" x 48"', NULL, 'Tamaño derivado del propio código interno, no de ficha del fabricante | Material confirmado por título del catálogo: "Stainless Steel Flexible Hose Fitting for Automatic Sprinkler Systems" (fu-mech.com, 01-Mech-Flexible-Hose-NEW-V8_compressed.pdf).', NULL, NULL, 'Talla 1/2x48: medidas (26.8, 1200) mm (ver volumen_metodo)', 'Ficha PDF real (botón Download) fu-mech.com/product/mech-stainless-steel-flexible-hose-for-sprinkler-connection/, pág. 9, ''Style: MDFB - Braided Hose with Straight Nipple'', tabla cULus/FM: Hose Length 1200mm (48"), 1/2" thread, Hose Diameter O.D. 26.8mm.', 676.93, 'Cilindro real: π×(D/2)²×L = π×(26.8/2)²×1200 mm. Manguera flexible trenzada, genuinamente axisimétrica. Largo (1200mm=48") y O.D. (26.8mm) coinciden exactamente con el nombre del producto (1/2" X 48") y la tabla oficial estilo MDFB (braided) de la ficha real. No incluye las boquillas/niples de conexión en los extremos (volumen adicional menor).', 'alta (medida exacta que coincide con el nombre del producto, tabla oficial del fabricante)');
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SALPHD212', 'SOP ANTIS  LONG 2 1/2" PHD  FIG 031 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 7141.0, 0.7347391361036164, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron and carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada and Factory Mutual approved. Listed for use with PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance.  Versatile design allows for attachment at any angle and the ability to be used in a lateral or longitudinal bracing configuration.  The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting and joined together with a bracing element form a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '1/2"', NULL, 'Size: Pipe sizes 2” thru 8”. Can use 1” thru 2” SCH 40 pipe, structural steel, and PHD 12 gauge strut channel (1001 & 1201) as sway bracing elements. | Install: Place attachment around pipe to be braced, positioning brace attachment as needed, then tighten clamping bolts and nuts finger tight.  Insert brace component into fitting against back of jaw.  Tighten set screw finger tight, adjust brace angle as needed, then tighten set screw until hex head breaks off.  Then evenly torque clamping bolts until hex portion of clamping nuts break off. | Ordering: Specify figure number and sprinkler pipe size. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG031 2-1/2in (2.77 lbs, sin ambiguedad) + FIG030 (1.46 lbs) = 4.23 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 13 y 15.', 4.23, 1.92, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.productos_criticos (codigo, nombre_producto, marca, modelo, familia, movimiento_total, pct_acum, dominios_oficiales, tiene_dominio, creado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente, volumen_cm3, volumen_metodo, volumen_confianza) VALUES ('3SALPHD004', 'SOP ANTIS LONG 4" PHD FIG 031 - 030', 'PHD', 'RELIABLE', 'SOPORTERIA', 4560.0, 0.8255117539925998, 'phd-mfg.com', true, '2026-08-04 15:14:44.141571+00', 'Ductile iron and carbon steel', 'Electro-galvanized', 'Underwriters Laboratories listed for US and Canada and Factory Mutual approved. Listed for use with PHD sway brace components only.', 'Designed for bracing pipe against sway and seismic disturbance.  Versatile design allows for attachment at any angle and the ability to be used in a lateral or longitudinal bracing configuration.  The pipe attachment component of a sway brace system used in conjunction with a PHD Manufacturing structural attachment fitting and joined together with a bracing element form a complete sway brace assembly.  Sway brace assemblies are intended to be installed in accordance with NFPA 13 and the manufacturer’s installation instructions.', '4"', NULL, 'Size: Pipe sizes 2” thru 8”. Can use 1” thru 2” SCH 40 pipe, structural steel, and PHD 12 gauge strut channel (1001 & 1201) as sway bracing elements. | Install: Place attachment around pipe to be braced, positioning brace attachment as needed, then tighten clamping bolts and nuts finger tight.  Insert brace component into fitting against back of jaw.  Tighten set screw finger tight, adjust brace angle as needed, then tighten set screw until hex head breaks off.  Then evenly torque clamping bolts until hex portion of clamping nuts break off. | Ordering: Specify figure number and sprinkler pipe size. | Tamaño derivado del propio código interno, no de ficha del fabricante | Peso: FIG031 4in (3.30 lbs, sin ambiguedad) + FIG030 (1.46 lbs) = 4.76 lbs. Fuente: catalogo maestro FireProtectionSeismicCatalog_1216.pdf, paginas 13 y 15.', 4.76, 2.16, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.scrapes (id, codigo, dominio, url_fuente, descripcion, serie, precio, moneda, estado, detalle, scrapeado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente) VALUES (1521, '28DETKIDIO', 'kidde.com', 'https://www.kidde.com/products/detect/4in-smoke-alarm-aa-battery-powered', 'Smoke Alarm, AA Battery Powered, modelo 10SDR. Diseño compacto de 4 para espacios pequeños. Tecnología de sensado mejorada para reducir falsas alarmas por cocina.', '10SDR (sucesor de 0914E)', NULL, NULL, 'ok', 'Nuestro código (0914E, iónico, batería 9V) fue descontinuado por Kidde; el modelo 10SDR es su reemplazo directo confirmado por fuente externa ("Kidde i9040 (0914/0914E)...Upgraded to 10SDR"). Tecnología de sensado y tipo de batería (AA vs 9V) cambiaron respecto al original.', '2026-08-05 03:14:04.38566+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.scrapes (id, codigo, dominio, url_fuente, descripcion, serie, precio, moneda, estado, detalle, scrapeado_en, material, acabado, aprobaciones, funcion_texto, tamano, k_factor, specs_adicionales, peso_lbs, peso_kg, dimensiones_texto, dimensiones_fuente) VALUES (697, '42RELPQC12', 'reliablesprinkler.com', 'https://www.reliablesprinkler.com/product/f1fr56-series-quick-response-sprinklers/', 'K Factor: 5.6 (80) | Style List: Concealed Pendent, Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall', 'F1FR56 Series Quick Response Sprinklers | Reliable Sprinkler', NULL, NULL, 'ok', 'Confianza alta: K-factor K5.6, 26 candidato(s), puntaje tipo 2.', '2026-08-04 20:20:22.679723+00', NULL, NULL, NULL, NULL, NULL, '5.6 (80)', 'Style List: Concealed Pendent, Horizontal Sidewall, Intermediate Level Upright, Pendent, Upright, Vertical Sidewall', NULL, NULL, NULL, NULL);
